    if (!dmesgFile) {
        dmesgFile = fopen("dmesg.txt", "w");
        if (!dmesgFile)
            dmesgFile = stderr;
    }
#endif

    if (codalLogStore.write(buf, len) != 0)
        return; // if message too long, skip

#ifdef LOG_TO_FILE
