// this type alias is required for backward compatibility
// it gets overriden in microbit (DigitalPin is an enum over there)
enum DigitalPin {
    P0 = DAL.CFG_PIN_P0,
    P1 = DAL.CFG_PIN_P1,
    P2 = DAL.CFG_PIN_P2,
    P3 = DAL.CFG_PIN_P3,
