namespace helpers {
    export type TilemapFactory = (name: string) => tiles.TileMapData;
    export type ImageFactory = (name: string) => Image;
    export type TileFactory = (name: string) => Image;
    export type AnimationFactory = (name: string) => Image[];
    export type SongFactory = (name: string) => Buffer;

    interface Factory {
        kind: string;
        factory: (name: string) => any;
    }

    let factories: Factory[];

    export function _registerFactory(kind: string, factory: (name: string) => any) {
        if (!factories) factories = [];
        factories.push({
            kind,
            factory
        });
    }

    export function _getFactoryInstance(kind: string, name: string) {
        if (factories) {
            for (const factory of factories) {
                if (factory.kind === kind) {
                    let data = factory.factory(name);
                    if (data) return data;
                }
            }
        }
        return null;
    }

    // Deprecated; use helpers._registerFactory("tilemap", name)
    export function registerTilemapFactory(factory: TilemapFactory) {
        _registerFactory("tilemap", factory);
    }

    export function getTilemapByName(name: string) {
        return _getFactoryInstance("tilemap", name);
    }

    export function getImageByName(name: string) {
        return _getFactoryInstance("image", name);
    }

    export function getAnimationByName(name: string) {
        return _getFactoryInstance("animation", name);
    }

    export function getTileByName(name: string) {
        return _getFactoryInstance("tile", name);
    }

    export function getSongByName(name: string) {
        return _getFactoryInstance("song", name);
    }
}

game.background.ts:
enum BackgroundAlignment {
    //% block="left"
    Left = 1,
    //% block="right"
    Right,
    //% block="top"
    Top,
    //% block="bottom"
    Bottom,
    //% block="center"
    Center
}

namespace scene {
    export class Background {
        color: number;
        _image: Image;
        camera: Camera;
        private _layers: BackgroundLayer[];

        constructor(camera: Camera) {
            this.color = 0;
            this.camera = camera;
            this._layers = [];
        }

        public addLayer(pic: Image, distance: number, alignment: BackgroundAlignment) {
            const layer = new BackgroundLayer(distance, alignment, pic);
            this._layers.push(layer);
            this._layers.sort((a, b) => b.distance - a.distance);
            return layer;
        }

        get image() {
            if (!this._image) {
                this._image = image.create(screen.width, screen.height);
            }
            return this._image;
        }

        set image(image: Image) {
            this._image = image;
        }

        hasBackgroundImage(): boolean {
            return !!this._image;
        }

        draw() {
            screen.fill(this.color);
            if (this._image)
                screen.drawTransparentImage(this._image, 0, 0)
            if (this._layers) {
                this._layers.forEach(layer => {
                    // compute displacement based on distance
                    const ox = Math.round(this.camera.drawOffsetX / (1 + layer.distance));
                    const oy = Math.round(this.camera.drawOffsetY / (1 + layer.distance));
                    layer.draw(ox, oy);
                });
            }
        }
    }


    export class BackgroundLayer {
        distance: number;
        img: Image;
        repeatX: boolean;
        repeatY: boolean;
        alignX: BackgroundAlignment;
        alignY: BackgroundAlignment;

        constructor(distance: number, alignment: BackgroundAlignment, img: Image) {
            this.distance = Math.max(1, distance);
            this.img = img;
            switch (alignment) {
                case BackgroundAlignment.Center:
                    this.repeatX = true;
                    this.repeatY = true;
                    this.alignX = BackgroundAlignment.Center;
                    this.alignY = BackgroundAlignment.Center;
                    break;
                case BackgroundAlignment.Left:
                case BackgroundAlignment.Right:
                    this.repeatX = false;
                    this.repeatY = true;
                    this.alignX = alignment;
                    this.alignY = BackgroundAlignment.Center;
                    break;
                case BackgroundAlignment.Top:
                case BackgroundAlignment.Bottom:
                    this.repeatX = true;
                    this.repeatY = false;
                    this.alignX = BackgroundAlignment.Center;
                    this.alignY = alignment;
                    break;
            }
        }

        draw(offsetX: number, offsetY: number) {
            const w = screen.width;
            const h = screen.height;
            const pw = this.img.width;
            const ph = this.img.height;

            if (!pw || !ph) return; // empty image.

            // left, top aligned
            let rx = -offsetX;
            let ry = -offsetY;

            switch (this.alignX) {
                case BackgroundAlignment.Right: rx -= (w + pw); break;
                case BackgroundAlignment.Center: rx -= (w + pw) >> 1; break;
            }
            switch (this.alignY) {
                case BackgroundAlignment.Bottom: ry -= (h + ph); break;
                case BackgroundAlignment.Center: ry -= (h + ph) >> 1; break;
            }

            rx %= w; if (rx < 0) rx += w;
            ry %= h; if (ry < 0) ry += h;

            // avoid subpixel aliasing
            rx = Math.floor(rx);
            ry = Math.floor(ry);

            let y = 0;
            let py = 0;
            while (y < h) {
                py = y % ph;
                let dh = Math.min(ph - py, h - ry);
                let x = 0;
                let rxl = rx;
                while (x < w) {
                    let px = x % pw;
                    let dw = Math.min(pw - px, w - rxl);
                    screen.drawImage(this.img, rxl, ry);
                    rxl = (rxl + dw) % w;
                    x += this.repeatX ? dw : w;
                }
                ry = (ry + dh) % h;
                y += this.repeatY ? dh : h;
            }
        }
    }
}

game.basesprite.ts:
interface SpriteLike {
    z: number;
    id: number;
    flags?: number;

    __update(camera: scene.Camera, dt: number): void;
    __draw(camera: scene.Camera): void;
    __serialize(offset: number): Buffer;
}

namespace sprites {
    export class BaseSprite implements SpriteLike {
        protected _z: number;
        id: number;

        constructor(z: number) {
            this.z = z;

            // this assigns the sprite an id as a side effect
            game.currentScene().addSprite(this);
        }

        __visible(): boolean {
            return true;
        }

        get z(): number {
            return this._z;
        }

        set z(v: number) {
            if (this._z !== v) {
                this._z = v;
                game.currentScene().flags |= scene.Flag.NeedsSorting;
            }
        }

        __draw(camera: scene.Camera) {
            if (this.__visible()) {
                this.__drawCore(camera);
            }
        }

        __drawCore(camera: scene.Camera) { }

        __update(camera: scene.Camera, dt: number) { }

        __serialize(offset: number): Buffer { return undefined }
    }
}

game.camera.ts:
namespace scene {
    export class Camera {
        // coordinate used for all physics computation
        protected _offsetX: number;
        protected _offsetY: number;

        // coordinate used for draw sprites, may including shaking
        drawOffsetX: number;
        drawOffsetY: number;
        sprite: Sprite;
        protected _lastUpdatedSpriteX: number;
        protected _lastUpdatedSpriteY: number;

        protected shakeStartTime: number;
        protected shakeDuration: number;
        protected shakeAmplitude: number;

        constructor() {
            this._offsetX = 0;
            this._offsetY = 0;

            this.drawOffsetX = 0;
            this.drawOffsetY = 0;
        }

        get offsetX() {
            return this._offsetX;
        }
        set offsetX(v: number) {
            const scene = game.currentScene();
            if (scene.tileMap && scene.tileMap.enabled) {
                this._offsetX = Math.floor(scene.tileMap.offsetX(v));
            } else {
                this._offsetX = Math.floor(v);
            }
        }
        get offsetY() {
            return this._offsetY;
        }
        set offsetY(v: number) {
            const scene = game.currentScene();
            if (scene.tileMap && scene.tileMap.enabled) {
                this._offsetY = Math.floor(scene.tileMap.offsetY(v));
            } else {
                this._offsetY = Math.floor(v);
            }
        }

        get x() {
            return this.offsetX + (screen.width >> 1);
        }
        get y() {
            return this.offsetY + (screen.height >> 1);
        }
        get left() {
            return this.offsetX;
        }
        get right() {
            return this.offsetX + screen.width;
        }
        get top() {
            return this.offsetY;
        }
        get bottom() {
            return this.offsetY + screen.height;
        }

        shake(amplitude: number = 4, duration: number = 1000) {
            if (amplitude <= 0 || duration <= 0) {
                this.shakeStartTime = undefined;
            } else {
                // this overrides any existing shake operation
                this.shakeStartTime = control.millis();
                this.shakeAmplitude = amplitude;
                this.shakeDuration = duration;
                // don't reset offset, will be recomputed in update
            }
        }

        isUpdated() {
            return !this.sprite || (this.sprite.x === this._lastUpdatedSpriteX && this.sprite.y === this._lastUpdatedSpriteY);
        }

        update() {
            // if sprite, follow sprite
            if (this.sprite) {
                this._lastUpdatedSpriteX = this.sprite.x;
                this._lastUpdatedSpriteY = this.sprite.y;
                this.offsetX = this.sprite.left + (this.sprite.width >> 1) - (screen.width >> 1);
                this.offsetY = this.sprite.top + (this.sprite.width >> 1) - (screen.height >> 1);
            }

            this.drawOffsetX = this.offsetX;
            this.drawOffsetY = this.offsetY;

            // apply shake if needed
            if (this.shakeStartTime !== undefined) {
                const elapsed = control.millis() - this.shakeStartTime;
                if (elapsed >= this.shakeDuration) {
                    // we are done!
                    this.shakeStartTime = undefined;
                } else {
                    // compute new shake
                    const percentComplete = elapsed / this.shakeDuration;
                    const dampStart = 0.75;
                    let damp = 1;
                    if (percentComplete >= dampStart)
                        damp = Math.max(0, 1 - percentComplete);
                    const f = this.shakeAmplitude * damp;
                    const x = (Math.random() * f) >> 0;
                    const y = (Math.random() * f) >> 0;
                    // apply to offset
                    this.drawOffsetX += x;
                    this.drawOffsetY += y;
                }
            }
        }
    }
}

game.console.ts:
namespace game.consoleOverlay {
    let consoleColor = 1;
    let consoleStrings: string[];
    let tabSize = 8;
    const marginx = 4;
    const marginy = 2;
    const consoleFont = image.font5;
    const consoleLines = Math.floor(screen.height / (consoleFont.charHeight + marginy)) - 1;
    const consoleColumns = Math.floor((screen.width - 2 * marginx) / consoleFont.charWidth);
    console.addListener(listener);

    export function isVisible() {
        return !!consoleStrings;
    }

    export function clear() {
        consoleStrings = [];
    }

    export function setVisible(value: boolean, col?: number) {
        if (value != !!consoleStrings)
            consoleStrings = value ? [] : undefined;
        if (col !== undefined)
            consoleColor = col;
    }

    function listener(priority: ConsolePriority, text: string) {
        if (!consoleStrings || !text)
            return;

        // split text into lines
        text.split("\n")
            .filter(line => !!line)
            .forEach(line => {
                for (let j = 0; j < line.length; j += consoleColumns) {
                    consoleStrings.push(line.slice(j, j + consoleColumns));
                }
            });

        if (consoleStrings.length > consoleLines) {
            consoleStrings.splice(0, consoleStrings.length - consoleLines);
        }
    }

    export function draw() {
        if (!consoleStrings || scene.systemMenu.isVisible()) return;
        const height = consoleFont.charHeight + marginy;
        const top = 2 + (game.stats ? height : 0);
        for (let i = 0; i < consoleStrings.length; ++i) {
            if (consoleStrings[i].indexOf("\t") >= 0) {
                const t = consoleStrings[i].split("\t");
                let tOff = 0;
                for (let tab of t) {
                    let padding = tabSize - ((tOff + tab.length) % tabSize)
                    screen.print(tab, marginx + (tOff * consoleFont.charWidth), top + i * height, consoleColor, consoleFont);
                    tOff += tab.length + padding;
                }
            }
            else
                screen.print(consoleStrings[i], marginx, top + i * height, consoleColor, consoleFont);
        }
    }
}

