namespace particles {
    enum Flag {
        enabled = 1 << 0,
        destroyed = 1 << 1,
        relativeToCamera = 1 << 2
    }

    // maximum count of sources before removing previous sources
    //% whenUsed
    const MAX_SOURCES = (() => {
        const sz = control.ramSize();
        if (sz <= 1024 * 100) {
            return 8;
        } else if (sz <= 1024 * 200) {
            return 16;
        } else {
            return 50;
        }
    })();
    const TIME_PRECISION = 10; // time goes down to down to the 1<<10 seconds
    let lastUpdate: number;

    /**
     * A single particle
     */
    //% maxBgInstances=200
    export class Particle {
        _x: Fx8;
        _y: Fx8;
        vx: Fx8;
        vy: Fx8;
        lifespan: number;
        next: Particle;
        data?: number;
        color?: number;
    }

    /**
     * An anchor for a Particle to originate from
     */
    export interface ParticleAnchor {
        x: number;
        y: number;
        vx?: number;
        vy?: number;
        width?: number;
        height?: number;
        image?: Image;
        flags?: number;
        setImage?: (i: Image) => void;
    }

    /**
     * A source of particles
     */
    export class ParticleSource extends sprites.BaseSprite {
        /**
         * A relative ranking of this sources priority
         * When necessary, a source with a lower priority will
         * be culled before a source with a higher priority.
         */
        priority: number;
        _dt: number;
        /**
         * The anchor this source is currently attached to
         */
        anchor: ParticleAnchor;
        /**
         * Time to live in milliseconds. The lifespan decreases by 1 on each millisecond
         * and the source gets destroyed when it reaches 0.
         */
        lifespan: number;

        protected pFlags: number;
        protected head: Particle;
        protected timer: number;
        protected period: number;
        protected _factory: ParticleFactory;

        protected ax: Fx8;
        protected ay: Fx8;

        /**
         * @param anchor to emit particles from
         * @param particlesPerSecond rate at which particles are emitted
         * @param factory [optional] factory to generate particles with; otherwise,
         */
        constructor(anchor: ParticleAnchor, particlesPerSecond: number, factory?: ParticleFactory) {
            super(scene.SPRITE_Z)
            init();
            const sources = particleSources();

            // remove and immediately destroy oldest source if over MAX_SOURCES
            if (sources.length >= MAX_SOURCES) {
                sortSources(sources);
                const removedSource = sources.shift();
                removedSource.clear();
                removedSource.destroy();
            }

            this.pFlags = 0;
            this.setRate(particlesPerSecond);
            this.setAcceleration(0, 0);
            this.setAnchor(anchor);
            this.lifespan = undefined;
            this._dt = 0;
            this.priority = 0;
            this.setFactory(factory || particles.defaultFactory);
            sources.push(this);
            this.enabled = true;
        }

        __draw(camera: scene.Camera) {
            let current = this.head;
            const left = (this.pFlags & Flag.relativeToCamera) ? Fx.zeroFx8 : Fx8(camera.drawOffsetX);
            const top = (this.pFlags & Flag.relativeToCamera) ? Fx.zeroFx8 : Fx8(camera.drawOffsetY);

            while (current) {
                if (current.lifespan > 0)
                    this.drawParticle(current, left, top);
                current = current.next;
            }
        }

        _update(dt: number) {
            this.timer -= dt;

            if (this.lifespan !== undefined) {
                this.lifespan -= dt;
                if (this.lifespan <= 0) {
                    this.lifespan = undefined;
                    this.destroy();
                }
            } else if (this.anchor && this.anchor.flags !== undefined && (this.anchor.flags & sprites.Flag.Destroyed)) {
                this.lifespan = 750;
            }

            while (this.timer < 0 && this.enabled) {
                this.timer += this.period;
                const p = this._factory.createParticle(this.anchor);
                if (!p) continue; // some factories can decide to not produce a particle
                p.next = this.head;
                this.head = p;
            }

            if (!this.head) return;

            let current = this.head;

            this._dt += dt;
            let fixedDt = Fx8(this._dt);
            if (fixedDt) {
                do {
                    if (current.lifespan > 0) {
                        current.lifespan -= dt;
                        this.updateParticle(current, fixedDt)
                    }
                } while (current = current.next);
                this._dt = 0;
            } else {
                do {
                    current.lifespan -= dt;
                } while (current = current.next);
            }
        }

        _prune() {
            while (this.head && this.head.lifespan <= 0) {
                this.head = this.head.next;
            }

            if ((this.pFlags & Flag.destroyed) && !this.head) {
                const scene = game.currentScene();
                if (scene)
                    scene.allSprites.removeElement(this);
                const sources = particleSources();
                if (sources && sources.length)
                    sources.removeElement(this);
                this.anchor == undefined;
            }

            let current = this.head;
            while (current && current.next) {
                if (current.next.lifespan <= 0) {
                    current.next = current.next.next;
                } else {
                    current = current.next;
                }
            }
        }

        /**
         * Sets the acceleration applied to the particles
         */
        setAcceleration(ax: number, ay: number) {
            this.ax = Fx8(ax);
            this.ay = Fx8(ay);
        }

        /**
         * Enables or disables particles
         * @param on
         */
        setEnabled(on: boolean) {
            this.enabled = on;
        }

        /**
         * Sets whether the particle source is drawn relative to the camera or not
         * @param on
         */
        setRelativeToCamera(on: boolean) {
            if (on) this.pFlags |= Flag.relativeToCamera
            else this.pFlags = ~(~this.pFlags | Flag.relativeToCamera);
        }

        get enabled() {
            return !!(this.pFlags & Flag.enabled);
        }

        /**
         * Set whether this source is currently enabled (emitting particles) or not
         */
        set enabled(v: boolean) {
            if (v !== this.enabled) {
                this.pFlags = v ? (this.pFlags | Flag.enabled) : (this.pFlags ^ Flag.enabled);
                this.timer = 0;
            }
        }

        /**
         * Destroy the source
         */
        destroy() {
            // The `_prune` step will finishing destroying this Source once all emitted particles finish rendering
            this.enabled = false;
            this.pFlags |= Flag.destroyed;
            this._prune();
        }

        /**
         * Clear all particles emitted from this source
         */
        clear() {
            this.head = undefined;
        }

        /**
         * Set a anchor for particles to be emitted from
         * @param anchor
         */
        setAnchor(anchor: ParticleAnchor) {
            this.anchor = anchor;
        }

        /**
         * Sets the number of particle created per second
         * @param particlesPerSecond
         */
        setRate(particlesPerSecond: number) {
            this.period = Math.ceil(1000 / particlesPerSecond);
            this.timer = 0;
        }

        get factory(): ParticleFactory {
            return this._factory;
        }

        /**
         * Sets the particle factory
         * @param factory
         */
        setFactory(factory: ParticleFactory) {
            if (factory)
                this._factory = factory;
        }

        protected updateParticle(p: Particle, fixedDt: Fx8) {
            fixedDt = Fx.rightShift(fixedDt, TIME_PRECISION);

            p.vx = Fx.add(p.vx, Fx.mul(this.ax, fixedDt));
            p.vy = Fx.add(p.vy, Fx.mul(this.ay, fixedDt));

            p._x = Fx.add(p._x, Fx.mul(p.vx, fixedDt));
            p._y = Fx.add(p._y, Fx.mul(p.vy, fixedDt));
        }

        protected drawParticle(p: Particle, screenLeft: Fx8, screenTop: Fx8) {
            this._factory.drawParticle(p, Fx.sub(p._x, screenLeft), Fx.sub(p._y, screenTop));
        }
    }

    //% whenUsed
    export const defaultFactory = new particles.SprayFactory(20, 0, 60);

    /**
     * Creates a new source of particles attached to a sprite
     * @param sprite
     * @param particlesPerSecond number of particles created per second
     */
    export function createParticleSource(sprite: Sprite, particlesPerSecond: number): ParticleSource {
        return new ParticleSource(sprite, particlesPerSecond);
    }

    function init() {
        const scene = game.currentScene();
        if (scene.particleSources) return;
        scene.particleSources = [];
        lastUpdate = control.millis();
        game.onUpdate(updateParticles);
        game.onUpdateInterval(250, pruneParticles);
    }

    function updateParticles() {
        const sources = particleSources();
        if (!sources) return;
        sortSources(sources);

        const time = control.millis();
        const dt = time - lastUpdate;
        lastUpdate = time;

        for (let i = 0; i < sources.length; i++) {
            sources[i]._update(dt);
        }
    }

    function pruneParticles() {
        const sources = particleSources();
        if (sources) sources.slice(0, sources.length).forEach(s => s._prune());
    }

    function sortSources(sources: ParticleSource[]) {
        sources.sort((a, b) => (a.priority - b.priority || a.id - b.id));
    }

    /**
     * A source of particles where particles will occasionally change speed based off of each other
     */
    export class FireSource extends ParticleSource {
        protected galois: Math.FastRandom;

        constructor(anchor: ParticleAnchor, particlesPerSecond: number, factory?: ParticleFactory) {
            super(anchor, particlesPerSecond, factory);
            this.galois = new Math.FastRandom();
            this.z = 20;
        }

        updateParticle(p: Particle, fixedDt: Fx8) {
            super.updateParticle(p, fixedDt);
            if (p.next && this.galois.percentChance(30)) {
                p.vx = p.next.vx;
                p.vy = p.next.vy;
            }
        }
    }

    /**
     * A source of particles where the particles oscillate horizontally, and occasionally change
     * between a given number of defined states
     */
    export class BubbleSource extends ParticleSource {
        protected maxState: number;
        protected galois: Math.FastRandom;
        stateChangePercentage: number;
        oscillationPercentage: number

        constructor(anchor: ParticleAnchor, particlesPerSecond: number, maxState: number, factory?: ParticleFactory) {
            super(anchor, particlesPerSecond, factory);
            this.galois = new Math.FastRandom();
            this.maxState = maxState;
            this.stateChangePercentage = 3;
            this.oscillationPercentage = 4;
        }

        updateParticle(p: Particle, fixedDt: Fx8) {
            super.updateParticle(p, fixedDt);
            if (this.galois.percentChance(this.stateChangePercentage)) {
                if (p.data < this.maxState) {
                    p.data++;
                } else if (p.data > 0) {
                    p.data--;
                }
            }

            if (this.galois.percentChance(this.oscillationPercentage)) {
                p.vx = Fx.neg(p.vx);
            }
        }
    }

    export function clearAll() {
        const sources = particleSources();
        if (sources) {
            sources.forEach(s => s.clear());
            pruneParticles();
        }
    }

    /**
     * Stop all particle sources from creating any new particles
     */
    export function disableAll() {
        const sources = particleSources();
        if (sources) {
            sources.forEach(s => s.enabled = false);
            pruneParticles();
        }
    }

    /**
     * Allow all particle sources to create any new particles
     */
    export function enableAll() {
        const sources = particleSources();
        if (sources) {
            sources.forEach(s => s.enabled = true);
            pruneParticles();
        }
    }

    function particleSources() {
        const sources = game.currentScene().particleSources;
        return sources;
    }
}

game.physics.ts:
class PhysicsEngine {
    constructor() {
    }

    /**
     * Adds sprite to the physics
     * @param sprite
     */
    addSprite(sprite: Sprite) { }

    removeSprite(sprite: Sprite) { }

    /** move a single sprite **/
    moveSprite(s: Sprite, dx: Fx8, dy: Fx8) { }

    draw() { }

    /** Apply physics and collisions to all sprites **/
    move(dt: number) { }

    setMaxSpeed(speed: number) { }

    overlaps(sprite: Sprite): Sprite[] { return []; }
}

const MAX_TIME_STEP = 100; // milliseconds
const MIN_MOVE_GAP = Fx8(0.1);

const SPRITE_NO_TILE_OVERLAPS = SpriteFlag.GhostThroughTiles | sprites.Flag.Destroyed | SpriteFlag.RelativeToCamera;
const SPRITE_NO_WALL_COLLISION = SpriteFlag.GhostThroughWalls | sprites.Flag.IsClipping | sprites.Flag.Destroyed | SpriteFlag.RelativeToCamera;
const SPRITE_NO_SPRITE_OVERLAPS = SpriteFlag.GhostThroughSprites | sprites.Flag.Destroyed | SpriteFlag.RelativeToCamera;

class MovingSprite {
    constructor(
        public sprite: Sprite,
        // vx and vy when last updated
        public cachedVx: Fx8,
        public cachedVy: Fx8,
        // remaining x
        public dx: Fx8,
        public dy: Fx8,
        // how much to move per step
        public xStep: Fx8,
        public yStep: Fx8
    ) { }
}

/**
 * A physics engine that does simple AABB bounding box check
 */
class ArcadePhysicsEngine extends PhysicsEngine {
    protected sprites: Sprite[];
    protected map: sprites.SpriteMap;
    protected maxVelocity: Fx8;
    protected maxNegativeVelocity: Fx8;
    protected minSingleStep: Fx8;
    protected maxSingleStep: Fx8;

    constructor(maxVelocity = 500, minSingleStep = 2, maxSingleStep = 4) {
        super();
        this.sprites = [];
        this.map = new sprites.SpriteMap();
        this.maxSpeed = maxVelocity;
        this.maxStep = maxSingleStep;
        this.minStep = minSingleStep;
    }

    get maxSpeed(): number {
        return Fx.toInt(this.maxVelocity);
    }

    set maxSpeed(v: number) {
        this.maxVelocity = Fx8(v);
        this.maxNegativeVelocity = Fx.neg(this.maxVelocity);
    }

    get minStep(): number {
        return Fx.toInt(this.minSingleStep);
    }

    set minStep(v: number) {
        this.minSingleStep = Fx8(v);
    }

    get maxStep(): number {
        return Fx.toInt(this.maxSingleStep);
    }

    set maxStep(v: number) {
        this.maxSingleStep = Fx8(v);
    }

    setMaxSpeed(v: number) {
        this.maxSpeed = v;
    }

    addSprite(sprite: Sprite) {
        this.sprites.push(sprite);
        const tm = game.currentScene().tileMap;
        if (tm && tm.isOnWall(sprite)) {
            sprite.flags |= sprites.Flag.IsClipping;
        }
    }

    removeSprite(sprite: Sprite) {
        this.sprites.removeElement(sprite);
    }

    draw() {
        this.map.draw();
    }

    move(dt: number) {
        // Sprite movement logic is done in milliseconds to avoid rounding errors with Fx8 numbers
        const dtMs = Math.min(MAX_TIME_STEP, dt * 1000);
        const dt2 = Math.idiv(dtMs, 2);

        const scene = game.currentScene();

        const tileMap = scene.tileMap;
        const movingSprites = this.sprites
            .map(sprite => this.createMovingSprite(sprite, dtMs, dt2));

        // clear obstacles if moving on that axis
        this.sprites.forEach(s => {
            if (s.vx || s.vy) s.clearObstacles();
        });

        this.map.clear();
        this.map.resizeBuckets(this.sprites);

        const MAX_STEP_COUNT = Fx.toInt(
            Fx.idiv(
                Fx.imul(
                    Fx.div(
                        this.maxVelocity,
                        this.minSingleStep
                    ),
                    dtMs
                ),
                1000
            )
        );
        const overlapHandlers = scene.overlapHandlers.slice();

        // buffers store the moving sprites on each step; switch back and forth between the two
        let selected = 0;
        let buffers = [movingSprites, []];
        for (let count = 0; count < MAX_STEP_COUNT && buffers[selected].length !== 0; ++count) {
            const currMovers = buffers[selected];
            selected ^= 1;
            const remainingMovers = buffers[selected];

            for (let ms of currMovers) {
                const s = ms.sprite;
                // if still moving and speed has changed from a collision or overlap;
                // reverse direction if speed has reversed
                if (ms.cachedVx !== s._vx) {
                    if (s._vx == Fx.zeroFx8) {
                        ms.dx = Fx.zeroFx8;
                    } else if (s._vx < Fx.zeroFx8 && ms.cachedVx > Fx.zeroFx8
                        || s._vx > Fx.zeroFx8 && ms.cachedVx < Fx.zeroFx8) {
                        ms.dx = Fx.neg(ms.dx);
                        ms.xStep = Fx.neg(ms.xStep);
                    }

                    ms.cachedVx = s._vx;
                }
                if (ms.cachedVy !== s._vy) {
                    if (s._vy == Fx.zeroFx8) {
                        ms.dy = Fx.zeroFx8;
                    } else if (s._vy < Fx.zeroFx8 && ms.cachedVy > Fx.zeroFx8
                        || s._vy > Fx.zeroFx8 && ms.cachedVy < Fx.zeroFx8) {
                        ms.dy = Fx.neg(ms.dy);
                        ms.yStep = Fx.neg(ms.yStep);
                    }

                    ms.cachedVy = s._vy;
                }

                // identify how much to move in this step
                const stepX = Fx.abs(ms.xStep) > Fx.abs(ms.dx) ? ms.dx : ms.xStep;
                const stepY = Fx.abs(ms.yStep) > Fx.abs(ms.dy) ? ms.dy : ms.yStep;
                ms.dx = Fx.sub(ms.dx, stepX);
                ms.dy = Fx.sub(ms.dy, stepY);

                s._lastX = s._x;
                s._lastY = s._y;
                s._x = Fx.add(s._x, stepX);
                s._y = Fx.add(s._y, stepY);

                if (!(s.flags & SPRITE_NO_SPRITE_OVERLAPS) && s._kindsOverlappedWith.length) {
                    this.map.insertAABB(s);
                }
                if (tileMap && tileMap.enabled) {
                    this.tilemapCollisions(ms, tileMap);
                }

                // check for screen edge collisions
                const bounce = s.flags & sprites.Flag.BounceOnWall;
                if (s.flags & sprites.Flag.StayInScreen || (bounce && !tileMap)) {
                    this.screenEdgeCollisions(ms, bounce, scene.camera);
                }

                // if sprite still needs to move, add it to the next step of movements
                if (Fx.abs(ms.dx) > MIN_MOVE_GAP || Fx.abs(ms.dy) > MIN_MOVE_GAP) {
                    remainingMovers.push(ms);
                }
            }

            // this step is done; check collisions between sprites
            this.spriteCollisions(currMovers, overlapHandlers);
            // clear moving sprites buffer for next step
            while (currMovers.length) currMovers.pop();
        }
    }

    protected createMovingSprite(sprite: Sprite, dtMs: number, dt2: number): MovingSprite {
        const ovx = this.constrain(sprite._vx);
        const ovy = this.constrain(sprite._vy);
        sprite._lastX = sprite._x;
        sprite._lastY = sprite._y;

        if (sprite._ax) {
            sprite._vx = Fx.add(
                sprite._vx,
                Fx.idiv(
                    Fx.imul(
                        sprite._ax,
                        dtMs
                    ),
                    1000
                )
            );
        } else if (sprite._fx) {
            const fx = Fx.idiv(
                Fx.imul(
                    sprite._fx,
                    dtMs
                ),
                1000
            );
            const c = Fx.compare(sprite._vx, fx);
            if (c < 0) // v < f, v += f
                sprite._vx = Fx.min(Fx.zeroFx8, Fx.add(sprite._vx, fx));
            else if (c > 0) // v > f, v -= f
                sprite._vx = Fx.max(Fx.zeroFx8, Fx.sub(sprite._vx, fx));
            else
                sprite._vx = Fx.zeroFx8
        }

        if (sprite._ay) {
            sprite._vy = Fx.add(
                sprite._vy,
                Fx.idiv(
                    Fx.imul(
                        sprite._ay,
                        dtMs
                    ),
                    1000
                )
            );
        } else if (sprite._fy) {
            const fy = Fx.idiv(
                Fx.imul(
                    sprite._fy,
                    dtMs
                ),
                1000
            );
            const c = Fx.compare(sprite._vy, fy);
            if (c < 0) // v < f, v += f
                sprite._vy = Fx.min(Fx.zeroFx8, Fx.add(sprite._vy, fy));
            else if (c > 0) // v > f, v -= f
                sprite._vy = Fx.max(Fx.zeroFx8, Fx.sub(sprite._vy, fy));
            else
                sprite._vy = Fx.zeroFx8;
        }

        sprite._vx = this.constrain(sprite._vx);
        sprite._vy = this.constrain(sprite._vy);

        const dx = Fx8(Fx.toFloat(Fx.add(sprite._vx, ovx)) * dt2 / 1000);
        const dy = Fx8(Fx.toFloat(Fx.add(sprite._vy, ovy)) * dt2 / 1000);

        let xStep = dx;
        let yStep = dy;

        // make step increments smaller until under max step size
        while (Fx.abs(xStep) > this.maxSingleStep || Fx.abs(yStep) > this.maxSingleStep) {
            if (Fx.abs(xStep) > this.minSingleStep) {
                xStep = Fx.idiv(xStep, 2);
            }
            if (Fx.abs(yStep) > this.minSingleStep) {
                yStep = Fx.idiv(yStep, 2);
            }
        }

        return new MovingSprite(
            sprite,
            sprite._vx,
            sprite._vy,
            dx,
            dy,
            xStep,
            yStep
        );
    }

    protected spriteCollisions(movedSprites: MovingSprite[], handlers: scene.OverlapHandler[]) {
        control.enablePerfCounter("phys_collisions");
        if (!handlers.length) return;

        // clear the overlap lists on all sprites
        for (const sprite of this.sprites) {
            sprite._alreadyChecked = undefined;
        }

        for (const bucket of this.map.filledBuckets) {
            if (bucket.length === 1) continue;

            for (const sprite of bucket) {
                if (sprite.flags & SPRITE_NO_SPRITE_OVERLAPS) continue;

                for (const overlapper of bucket) {
                    if (overlapper === sprite) continue;
                    const thisKind = sprite.kind();
                    const otherKind = overlapper.kind();

                    // the sprite with the higher id maintains the overlap lists
                    const higher = sprite.id > overlapper.id ? sprite : overlapper;
                    const lower = higher === sprite ? overlapper : sprite;

                    if (!higher._alreadyChecked) {
                        higher._alreadyChecked = [];
                    }

                    // skip if we already compared these two
                    if (higher._alreadyChecked.indexOf(lower.id) !== -1) continue;

                    higher._alreadyChecked.push(lower.id);

                    // skip if already overlapping
                    if (higher._overlappers.indexOf(lower.id) !== -1) continue;

                    // skip if there is no overlap event between these two kinds of sprites
                    if (sprite._kindsOverlappedWith.indexOf(otherKind) === -1) continue;

                    // perform the actual overlap check
                    if (!higher.overlapsWith(lower)) continue;

                    // invoke all matching overlap event handlers
                    for (const h of handlers) {
                        if ((h.kind === thisKind && h.otherKind === otherKind)
                            || (h.kind === otherKind && h.otherKind === thisKind)) {
                            higher._overlappers.push(lower.id);
                            control.runInParallel(() => {
                                if (!((sprite.flags | overlapper.flags) & SPRITE_NO_SPRITE_OVERLAPS)) {
                                    if (thisKind === h.kind) {
                                        h.handler(sprite, overlapper)
                                    }
                                    else {
                                        h.handler(overlapper, sprite)
                                    }
                                }
                                higher._overlappers.removeElement(lower.id);
                            });
                        }
                    }
                }
            }
        }
    }

    protected screenEdgeCollisions(movingSprite: MovingSprite, bounce: number, camera: scene.Camera) {
        let s = movingSprite.sprite;
        if (!s.isStatic()) s.setHitbox();
        if (!camera.isUpdated()) camera.update();

        let offset = Fx.toFloat(s._hitbox.left) - camera.offsetX;
        if (offset < 0) {
            s.left -= offset;
            if (bounce) s.vx = -s.vx;
        }
        else if ((offset = Fx.toFloat(s._hitbox.right) - camera.offsetX - screen.width) > 0) {
            s.right -= offset;
            if (bounce) s.vx = -s.vx;
        }
        if ((offset = Fx.toFloat(s._hitbox.top) - camera.offsetY) < 0) {
            s.top -= offset;
            if (bounce) s.vy = -s.vy;
        }
        else if ((offset = Fx.toFloat(s._hitbox.bottom) - camera.offsetY - screen.height) > 0) {
            s.bottom -= offset;
            if (bounce) s.vy = -s.vy;
        }
    }

    protected tilemapCollisions(movingSprite: MovingSprite, tm: tiles.TileMap) {
        const s = movingSprite.sprite;
        // if the sprite is already clipping into a wall,
        // allow free movement rather than randomly 'fixing' it
        if (s.flags & sprites.Flag.IsClipping) {
            if (!tm.isOnWall(s)) {
                s.flags &= ~sprites.Flag.IsClipping;
            }
        }
        if (!s.isStatic()) s.setHitbox();
        const hbox = s._hitbox;
        const tileScale = tm.scale;
        const tileSize = 1 << tileScale;

        const xDiff = Fx.sub(
            s._x,
            s._lastX
        );

        const yDiff = Fx.sub(
            s._y,
            s._lastY
        );

        if (!(s.flags & SPRITE_NO_WALL_COLLISION)) {
            if (xDiff !== Fx.zeroFx8) {
                const right = xDiff > Fx.zeroFx8;
                const x0 = Fx.toIntShifted(
                    Fx.add(
                        right ?
                            Fx.add(hbox.right, Fx.oneFx8)
                            :
                            Fx.sub(hbox.left, Fx.oneFx8),
                        Fx.oneHalfFx8
                    ),
                    tileScale
                );

                const collidedTiles: sprites.StaticObstacle[] = [];

                // check collisions with tiles sprite is moving towards horizontally
                for (
                    let y = Fx.sub(hbox.top, yDiff);
                    y < Fx.iadd(tileSize, Fx.sub(hbox.bottom, yDiff));
                    y = Fx.iadd(tileSize, y)
                ) {
                    const y0 = Fx.toIntShifted(
                        Fx.add(
                            Fx.min(
                                y,
                                Fx.sub(
                                    hbox.bottom,
                                    yDiff
                                )
                            ),
                            Fx.oneHalfFx8
                        ),
                        tileScale
                    );

                    if (tm.isObstacle(x0, y0)) {
                        const obstacle = tm.getObstacle(x0, y0);
                        if (!collidedTiles.some(o => o.tileIndex === obstacle.tileIndex)) {
                            collidedTiles.push(obstacle);
                        }
                    }
                }

                if (collidedTiles.length) {
                    const collisionDirection = right ? CollisionDirection.Right : CollisionDirection.Left;
                    s._x = Fx.sub(
                        right ?
                            Fx.sub(
                                Fx8(x0 << tileScale),
                                hbox.width
                            )
                            :
                            Fx8((x0 + 1) << tileScale),
                        hbox.ox
                    );

                    for (const tile of collidedTiles) {
                        if(!(s.flags & SPRITE_NO_WALL_COLLISION)) {
                            s.registerObstacle(collisionDirection, tile, tm);
                        }
                    }

                    if (s.flags & sprites.Flag.DestroyOnWall) {
                        s.destroy();
                    } else if (s._vx === movingSprite.cachedVx && !(s.flags & SPRITE_NO_WALL_COLLISION)) {
                        // sprite collision event didn't change velocity in this direction;
                        // apply normal updates
                        if (s.flags & sprites.Flag.BounceOnWall) {
                            if ((!right && s.vx < 0) || (right && s.vx > 0)) {
                                s._vx = Fx.neg(s._vx);
                                movingSprite.xStep = Fx.neg(movingSprite.xStep);
                                movingSprite.dx = Fx.neg(movingSprite.dx);
                            }
                        } else {
                            movingSprite.dx = Fx.zeroFx8;
                            s._vx = Fx.zeroFx8;
                        }
                    } else if (Math.sign(Fx.toInt(s._vx)) === Math.sign(Fx.toInt(movingSprite.cachedVx))) {
                        // sprite collision event changed velocity,
                        // but still facing same direction; prevent further movement this update.
                        movingSprite.dx = Fx.zeroFx8;
                    }
                }
            }

            if (yDiff !== Fx.zeroFx8) {
                const down = yDiff > Fx.zeroFx8;
                const y0 = Fx.toIntShifted(
                    Fx.add(
                        down ?
                            Fx.add(hbox.bottom, Fx.oneFx8)
                            :
                            Fx.sub(hbox.top, Fx.oneFx8),
                        Fx.oneHalfFx8
                    ),
                    tileScale
                );
                const collidedTiles: sprites.StaticObstacle[] = [];

                // check collisions with tiles sprite is moving towards vertically
                for (
                    let x = hbox.left;
                    x < Fx.iadd(tileSize, hbox.right);
                    x = Fx.iadd(tileSize, x)
                ) {
                    const x0 = Fx.toIntShifted(
                        Fx.add(
                            Fx.min(
                                x,
                                hbox.right
                            ),
                            Fx.oneHalfFx8
                        ),
                        tileScale
                    );

                    if (tm.isObstacle(x0, y0)) {
                        const obstacle = tm.getObstacle(x0, y0);
                        if (!collidedTiles.some(o => o.tileIndex === obstacle.tileIndex)) {
                            collidedTiles.push(obstacle);
                        }
                    }
                }

                if (collidedTiles.length) {
                    const collisionDirection = down ? CollisionDirection.Bottom : CollisionDirection.Top;
                    s._y = Fx.sub(
                        down ?
                            Fx.sub(
                                Fx8(y0 << tileScale),
                                hbox.height
                            )
                            :
                            Fx8((y0 + 1) << tileScale),
                        hbox.oy
                    );

                    for (const tile of collidedTiles) {
                        if(!(s.flags & SPRITE_NO_WALL_COLLISION)) {
                            s.registerObstacle(collisionDirection, tile, tm);
                        }
                    }

                    if (s.flags & sprites.Flag.DestroyOnWall) {
                        s.destroy();
                    } else if (s._vy === movingSprite.cachedVy && !(s.flags & SPRITE_NO_WALL_COLLISION)) {
                        // sprite collision event didn't change velocity in this direction;
                        // apply normal updates
                        if (s.flags & sprites.Flag.BounceOnWall) {
                            if ((!down && s.vy < 0) || (down && s.vy > 0)) {
                                s._vy = Fx.neg(s._vy);
                                movingSprite.yStep = Fx.neg(movingSprite.yStep);
                                movingSprite.dy = Fx.neg(movingSprite.dy);
                            }
                        } else {
                            movingSprite.dy = Fx.zeroFx8;
                            s._vy = Fx.zeroFx8;
                        }
                    } else if (Math.sign(Fx.toInt(s._vy)) === Math.sign(Fx.toInt(movingSprite.cachedVy))) {
                        // sprite collision event changed velocity,
                        // but still facing same direction; prevent further movement this update.
                        movingSprite.dy = Fx.zeroFx8;
                    }
                }
            }
        }


        if (!(s.flags & SPRITE_NO_TILE_OVERLAPS)) {
            // Now that we've moved, check all of the tiles underneath the current position
            // for overlaps
            const overlappedTiles: tiles.Location[] = [];
            for (
                let x = hbox.left;
                x < Fx.iadd(tileSize, hbox.right);
                x = Fx.iadd(tileSize, x)
            ) {
                const x0 = Fx.toIntShifted(
                    Fx.add(
                        Fx.min(
                            x,
                            hbox.right
                        ),
                        Fx.oneHalfFx8
                    ),
                    tileScale
                );
                for (
                    let y = hbox.top;
                    y < Fx.iadd(tileSize, hbox.bottom);
                    y = Fx.iadd(tileSize, y)
                ) {
                    const y0 = Fx.toIntShifted(
                        Fx.add(
                            Fx.min(
                                y,
                                hbox.bottom
                            ),
                            Fx.oneHalfFx8
                        ),
                        tileScale
                    );

                    // if the sprite can move through walls, it can overlap the underlying tile.
                    if (!tm.isObstacle(x0, y0) || !!(s.flags & sprites.Flag.GhostThroughWalls)) {
                        overlappedTiles.push(tm.getTile(x0, y0));
                    }
                }
            }

            if (overlappedTiles.length) {
                this.tilemapOverlaps(s, overlappedTiles);
            }
        }
    }

    /**
     * Given a sprite and a list of overlapped tiles, checks the overlap handlers and calls
     * the ones appropriate to the sprite and tile kind.
     * @param sprite the sprite
     * @param overlappedTiles the list of tiles the sprite is overlapping
     */
    protected tilemapOverlaps(sprite: Sprite, overlappedTiles: tiles.Location[]) {
        const alreadyHandled: tiles.Location[] = [];

        for (const tile of overlappedTiles) {
            if (alreadyHandled.some(l => l.column === tile.column && l.row === tile.row)) {
                continue;
            }
            alreadyHandled.push(tile);

            const tileOverlapHandlers = game.currentScene().tileOverlapHandlers;
            if (tileOverlapHandlers) {
                tileOverlapHandlers
                    .filter(h => h.spriteKind == sprite.kind() && h.tileKind.equals(tiles.getTileImage(tile)))
                    .forEach(h => h.handler(sprite, tile));
            }
        }
    }

    /**
     * Returns sprites that overlap with the given sprite. If type is non-zero, also filter by type.
     * @param sprite
     * @param layer
     */
    overlaps(sprite: Sprite): Sprite[] {
        return this.map.overlaps(sprite);
    }

    /** moves a sprite explicitly outside of the normal velocity changes **/
    public moveSprite(s: Sprite, dx: Fx8, dy: Fx8) {
        s._lastX = s._x;
        s._lastY = s._y;
        s._x = Fx.add(s._x, dx);
        s._y = Fx.add(s._y, dy);

        // if the sprite can collide with things, check tile map
        const tm = game.currentScene().tileMap;
        if (tm && tm.enabled) {
            const maxDist = Fx.toInt(this.maxSingleStep);
            // only check tile map if moving within a single step
            if (Math.abs(Fx.toInt(dx)) <= maxDist && Math.abs(Fx.toInt(dy)) <= maxDist) {
                const ms = new MovingSprite(
                    s,
                    s._vx,
                    s._vy,
                    dx,
                    dy,
                    dx,
                    dy
                );
                this.tilemapCollisions(ms, tm);
                // otherwise, accept movement...
            } else if (tm.isOnWall(s) && !this.canResolveClipping(s, tm)) {
                // if no luck, flag as clipping into a wall
                s.flags |= sprites.Flag.IsClipping;
            } else {
                // or clear clipping if no longer clipping
                s.flags &= ~sprites.Flag.IsClipping;
            }
        }
    }

    // Attempt to resolve clipping by moving the sprite slightly up / down / left / right
    protected canResolveClipping(s: Sprite, tm: tiles.TileMap) {
        if (s.flags & sprites.Flag.GhostThroughWalls) return false;
        if (!s.isStatic()) s.setHitbox();
        const hbox = s._hitbox;
        const sz = 1 << tm.scale;
        const maxMove = this.maxStep;
        const origY = s._y;
        const origX = s._x;
        const l = Fx.toInt(hbox.left);
        const r = Fx.toInt(hbox.right);
        const t = Fx.toInt(hbox.top);
        const b = Fx.toInt(hbox.bottom);

        {   // bump up and test;
            const offset = (b + 1) % sz;
            if (offset <= maxMove) {
                s._y = Fx.sub(
                    s._y,
                    Fx8(offset)
                );
                if (!tm.isOnWall(s)) {
                    return true;
                } else {
                    s._y = origY;
                }
            }
        }
        {   // bump down and test;
            const offset = (Math.floor(t / sz) + 1) * sz - t;
            if (offset <= maxMove) {
                s._y = Fx.add(
                    s._y,
                    Fx8(offset)
                );
                if (!tm.isOnWall(s)) {
                    return true;
                } else {
                    s._y = origY;
                }
            }
        }
        {   // bump left and test;
            const offset = (r + 1) % sz;
            if (offset <= maxMove) {
                s._x = Fx.sub(
                    s._x,
                    Fx8(offset)
                );
                if (!tm.isOnWall(s)) {
                    return true;
                } else {
                    s._x = origX;
                }
            }
        }
        {   // bump right and test;
            const offset = (Math.floor(l / sz) + 1) * sz - l;
            if (offset <= maxMove) {
                s._x = Fx.add(
                    s._x,
                    Fx8(offset)
                );
                if (!tm.isOnWall(s)) {
                    return true;
                } else {
                    s._x = origX;
                }
            }
        }

        // no trivial adjustment worked; it's going to clip for now
        return false;
    }

    protected constrain(v: Fx8) {
        return Fx.max(
            Fx.min(
                this.maxVelocity,
                v
            ),
            this.maxNegativeVelocity
        );
    }
}

game.prompt.ts:
namespace game {
    export const _KEYBOARD_CHANGE_EVENT = 7339;
    export const _KEYBOARD_ENTER_EVENT = 7340;
    export const _KEYBOARD_CANCEL_EVENT = 7341;

    export interface PromptTheme {
        colorPrompt: number;
        colorInput: number;
        colorInputHighlighted: number;
        colorInputText: number;
        colorAlphabet: number;
        colorCursor: number;
        colorBackground: number;
        colorBottomBackground: number;
        colorBottomText: number;
    }

    /**
     * Ask the player for a string value.
     * @param message The message to display on the text-entry screen
     * @param answerLength The maximum number of characters the user can enter (1 - 24)
     * @param useOnScreenKeyboard Force the simulator to use the on-screen keyboard for text entry
     */
    //% weight=10 help=game/ask-for-string
    //% blockId=gameaskforstring
    //% block="ask for string $message || and max length $answerLength use on-screen keyboard $useOnScreenKeyboard"
    //% message.shadow=text
    //% message.defl=""
    //% answerLength.defl="12"
    //% answerLength.min=1
    //% answerLength.max=24
    //% group="Prompt"
    export function askForString(message: any, answerLength = 12, useOnScreenKeyboard = false) {
        let p = new game.Prompt();
        const result = p.show(console.inspect(message), answerLength, useOnScreenKeyboard);
        return result;
    }


    //% whenUsed=true
    const font = image.font8; // FONT8-TODO
    //% whenUsed=true
    const PADDING = 4;

    //% whenUsed=true
    const NUM_LETTERS = 26;
    //% whenUsed=true
    const ALPHABET_ROW_LENGTH = 12;
    //% whenUsed=true
    const NUM_ROWS = Math.ceil(NUM_LETTERS / ALPHABET_ROW_LENGTH);
    //% whenUsed=true
    const INPUT_ROWS = 2;

    //% whenUsed=true
    const CONTENT_WIDTH = screen.width - PADDING * 2;
    //% whenUsed=true
    const CONTENT_HEIGHT = screen.height - PADDING * 2;
    //% whenUsed=true
    const CONTENT_TOP = PADDING;

    // Dimensions of a "cell" that contains a letter
    //% whenUsed=true
    const CELL_WIDTH = Math.floor(CONTENT_WIDTH / ALPHABET_ROW_LENGTH);
    //% whenUsed=true
    const CELL_HEIGHT = CELL_WIDTH;
    //% whenUsed=true
    const LETTER_OFFSET_X = Math.floor((CELL_WIDTH - font.charWidth) / 2);
    //% whenUsed=true
    const LETTER_OFFSET_Y = Math.floor((CELL_HEIGHT - font.charHeight) / 2);
    //% whenUsed=true
    const BLANK_PADDING = 1;
    //% whenUsed=true
    const ROW_LEFT = PADDING + Math.floor((CONTENT_WIDTH - (CELL_WIDTH * ALPHABET_ROW_LENGTH)) / 2);

    // Dimensions of the bottom bar
    //% whenUsed=true
    const BOTTOM_BAR_ALPHABET_MARGIN = 4;
    //% whenUsed=true
    const BOTTOM_BAR_HEIGHT = PADDING + BOTTOM_BAR_ALPHABET_MARGIN + CELL_HEIGHT;
    //% whenUsed=true
    const BOTTOM_BAR_BUTTON_WIDTH = PADDING * 2 + font.charWidth * 3;
    //% whenUsed=true
    const BOTTOM_BAR_TEXT_Y = (BOTTOM_BAR_HEIGHT - font.charHeight) / 2;
    //% whenUsed=true
    const BOTTOM_BAR_SHIFT_X = (BOTTOM_BAR_BUTTON_WIDTH - font.charWidth * 3) / 2;
    //% whenUsed=true
    const BOTTOM_BAR_CONFIRM_X = (BOTTOM_BAR_BUTTON_WIDTH - font.charWidth * 2) / 2;
    //% whenUsed=true
    const CONFIRM_BUTTON_LEFT = screen.width - BOTTOM_BAR_BUTTON_WIDTH;

    // Dimensions of the alphabet area
    //% whenUsed=true
    const ALPHABET_HEIGHT = NUM_ROWS * CELL_HEIGHT;
    //% whenUsed=true
    const ALPHABET_TOP = CONTENT_TOP + CONTENT_HEIGHT - ALPHABET_HEIGHT - BOTTOM_BAR_HEIGHT;
    //% whenUsed=true
    const ALPHABET_INPUT_MARGIN = 10;

    // Dimensions of area where text is input
    //% whenUsed=true
    const INPUT_HEIGHT = INPUT_ROWS * CELL_HEIGHT;
    //% whenUsed=true
    const INPUT_TOP = ALPHABET_TOP - INPUT_HEIGHT - ALPHABET_INPUT_MARGIN;

    //% whenUsed=true
    const lowerShiftText = "ABC";
    //% whenUsed=true
    const upperShiftText = "abc";
    //% whenUsed=true
    const digitsUpper = [" ", ",", ".", "?", "!", ":", ";", "\"", "(", ")"];
    //% whenUsed=true
    const confirmText = "OK";


    export class Prompt {
        theme: PromptTheme;

        message: string;
        answerLength: number;
        result: string;

        protected confirmPressed: boolean;
        protected cursorRow: number;
        protected cursorColumn: number;
        protected upper: boolean;
        protected useSystemKeyboard: boolean;

        protected renderable: scene.Renderable;
        protected selectionStart: number;
        protected selectionEnd: number;

        protected keyboardRows: number;
        protected keyboardColumns: number;

        private changeTime = 0;

        constructor(theme?: PromptTheme) {
            if (theme) {
                this.theme = theme;
            }
            else {
                this.theme = {
                    colorPrompt: 1,
                    colorInput: 3,
                    colorInputHighlighted: 5,
                    colorInputText: 1,
                    colorAlphabet: 1,
                    colorCursor: 7,
                    colorBackground: 15,
                    colorBottomBackground: 3,
                    colorBottomText: 1,
                };
            }
            this.cursorRow = 0;
            this.cursorColumn = 0;
            this.upper = false;
            this.result = "";
            this.keyboardColumns = ALPHABET_ROW_LENGTH;
            this.keyboardRows = NUM_ROWS;
            this.selectionStart = 0;
            this.selectionEnd = 0;
        }

        show(message: string, answerLength: number, useOnScreenKeyboard = false) {
            this.message = message;
            this.answerLength = answerLength;

            controller._setUserEventsEnabled(false);
            game.pushScene()

            this.createRenderable();
            this.confirmPressed = false;

            if (!useOnScreenKeyboard && control.deviceDalVersion() === "sim" && helpers._isSystemKeyboardSupported()) {
                this.useSystemKeyboard = true;
                helpers._promptForText(this.answerLength, this.numbersOnly());
                this.selectionEnd = 0;
                this.selectionStart = 0;
                control.onEvent(_KEYBOARD_CHANGE_EVENT, 0, () => {
                    this.result = helpers._getTextPromptString().substr(0, this.answerLength);

                    this.changeTime = game.runtime();

                    this.selectionStart = helpers._getTextPromptSelectionStart();
                    this.selectionEnd = helpers._getTextPromptSelectionEnd();
                })

                let cancelled = false;
                let finished = false;

                control.onEvent(_KEYBOARD_CANCEL_EVENT, 0, () => {
                    cancelled = true;
                });

                control.onEvent(_KEYBOARD_ENTER_EVENT, 0, () => {
                    finished = true;
                });

                pauseUntil(() => cancelled || finished);

                if (cancelled) {
                    this.useSystemKeyboard = false;
                    this.selectionStart = this.result.length;
                    this.selectionEnd = this.selectionStart;
                    this.registerHandlers();
                    pauseUntil(() => this.confirmPressed);
                }
            }
            else {
                this.useSystemKeyboard = false;
                this.registerHandlers();
                pauseUntil(() => this.confirmPressed);
            }

            game.popScene();
            controller._setUserEventsEnabled(true);

            return this.result;
        }

        protected numbersOnly() {
            return false;
        }

        protected createRenderable() {
            if (this.renderable) {
                this.renderable.destroy();
            }

            const promptText = new sprites.RenderText(this.message, CONTENT_WIDTH);
            let systemKeyboardText: sprites.RenderText;

            this.renderable = scene.createRenderable(-1, () => {
                promptText.draw(screen, (screen.width >> 1) - (promptText.width >> 1), CONTENT_TOP, this.theme.colorPrompt, 0, 2)
                this.drawInputArea();

                if (!this.useSystemKeyboard) {
                    this.drawKeyboard();
                    this.drawBottomBar();
                    return;
                }

                if (!systemKeyboardText) {
                    systemKeyboardText = new sprites.RenderText(helpers._getLocalizedInstructions(), CONTENT_WIDTH);
                }

                screen.fillRect(0, screen.height - (PADDING << 1) - systemKeyboardText.height, screen.width, screen.height, this.theme.colorBottomBackground);
                systemKeyboardText.draw(screen, PADDING, screen.height - PADDING - systemKeyboardText.height, this.theme.colorBottomText);
            });
        }

        protected drawInputArea() {
            const answerLeft = ROW_LEFT + Math.floor(
                ((CELL_WIDTH * ALPHABET_ROW_LENGTH) -
                    CELL_WIDTH * Math.min(this.answerLength, ALPHABET_ROW_LENGTH)) / 2);

            for (let i = 0; i < this.answerLength; i++) {
                const col = i % ALPHABET_ROW_LENGTH;
                const row = Math.floor(i / ALPHABET_ROW_LENGTH);

                if (this.selectionStart !== this.selectionEnd && i >= this.selectionStart && i < this.selectionEnd) {
                    screen.fillRect(
                        answerLeft + col * CELL_WIDTH,
                        INPUT_TOP + row * CELL_HEIGHT,
                        CELL_WIDTH,
                        CELL_HEIGHT,
                        this.theme.colorCursor
                    );
                }

                screen.fillRect(
                    answerLeft + col * CELL_WIDTH + BLANK_PADDING,
                    INPUT_TOP + row * CELL_HEIGHT + CELL_HEIGHT - 1,
                    CELL_WIDTH - BLANK_PADDING * 2,
                    1,
                    !this.useSystemKeyboard && !this.blink() && i === this.selectionStart ? this.theme.colorInputHighlighted : this.theme.colorInput
                );

                if (i < this.result.length) {
                    const char = this.result.charAt(i);
                    screen.print(
                        char,
                        answerLeft + col * CELL_WIDTH + LETTER_OFFSET_X,
                        INPUT_TOP + row * CELL_HEIGHT + LETTER_OFFSET_Y,
                        this.theme.colorInputText,
                        font
                    );
                }
            }

            // draw the blinking text cursor
            if (this.useSystemKeyboard) {
                if (this.selectionStart === this.selectionEnd && this.selectionStart < this.answerLength) {
                    const col = this.selectionStart % ALPHABET_ROW_LENGTH;
                    const row = Math.floor(this.selectionStart / ALPHABET_ROW_LENGTH);
                    if (!this.blink()) {
                        screen.fillRect(
                            answerLeft + col * CELL_WIDTH,
                            INPUT_TOP + row * CELL_HEIGHT,
                            1,
                            CELL_HEIGHT,
                            this.theme.colorCursor
                        );
                    }
                }
            }
        }

        protected drawKeyboard() {
            const top = screen.height - BOTTOM_BAR_HEIGHT - this.keyboardRows * CELL_HEIGHT - PADDING;
            const left = (screen.width >> 1) - ((CELL_WIDTH * this.keyboardColumns) >> 1)
            for (let j = 0; j < this.keyboardRows * this.keyboardColumns; j++) {
                const col = j % this.keyboardColumns;
                const row = Math.idiv(j, this.keyboardColumns);

                if (col === this.cursorColumn && row === this.cursorRow) {
                    screen.fillRect(
                        left + col * CELL_WIDTH,
                        top + row * CELL_HEIGHT,
                        CELL_WIDTH,
                        CELL_HEIGHT,
                        this.theme.colorCursor
                    )
                }

                screen.print(
                    this.getSymbolForIndex(j),
                    left + col * CELL_WIDTH + LETTER_OFFSET_X,
                    top + row * CELL_HEIGHT + LETTER_OFFSET_Y,
                    this.theme.colorAlphabet
                )
            }
        }

        protected drawBottomBar() {
            this.drawBottomBarBackground();
            this.drawShift(this.cursorRow === 3 && !(this.cursorColumn & 1));
            this.drawConfirm(this.cursorRow === 3 && !!(this.cursorColumn & 1));
        }

        protected drawBottomBarBackground() {
            screen.fillRect(0, screen.height - BOTTOM_BAR_HEIGHT, screen.width, BOTTOM_BAR_HEIGHT, this.theme.colorBottomBackground);
        }

        protected drawShift(highlighted: boolean) {
            if (highlighted) {
                screen.fillRect(
                    0,
                    screen.height - BOTTOM_BAR_HEIGHT,
                    BOTTOM_BAR_BUTTON_WIDTH,
                    BOTTOM_BAR_HEIGHT,
                    this.theme.colorCursor
                );
            }

            let shiftText = lowerShiftText;
            if (this.upper) {
                shiftText = upperShiftText;
            }
            screen.print(
                shiftText,
                BOTTOM_BAR_SHIFT_X,
                screen.height - BOTTOM_BAR_HEIGHT + BOTTOM_BAR_TEXT_Y,
                this.theme.colorBottomText
            )
        }

        protected drawConfirm(highlighted: boolean) {
            if (highlighted) {
                screen.fillRect(
                    CONFIRM_BUTTON_LEFT,
                    screen.height - BOTTOM_BAR_HEIGHT,
                    BOTTOM_BAR_BUTTON_WIDTH,
                    BOTTOM_BAR_HEIGHT,
                    this.theme.colorCursor
                );
            }

            screen.print(
                confirmText,
                CONFIRM_BUTTON_LEFT + BOTTOM_BAR_CONFIRM_X,
                screen.height - BOTTOM_BAR_HEIGHT + BOTTOM_BAR_TEXT_Y,
                this.theme.colorBottomText
            )
        }

        protected getSymbolForIndex(index: number) {
            return getCharForIndex(index, this.upper);
        }

        private registerHandlers() {
            controller.up.onEvent(SYSTEM_KEY_DOWN, () => {
                this.moveVertical(true);
            })

            controller.down.onEvent(SYSTEM_KEY_DOWN, () => {
                this.moveVertical(false);
            })

            controller.right.onEvent(SYSTEM_KEY_DOWN, () => {
                this.moveHorizontal(true);
            });

            controller.left.onEvent(SYSTEM_KEY_DOWN, () => {
                this.moveHorizontal(false);
            });

            controller.A.onEvent(SYSTEM_KEY_DOWN, () => {
                this.confirm();
            });

            controller.B.onEvent(SYSTEM_KEY_DOWN, () => {
                this.delete();
            });
        }

        protected moveVertical(up: boolean) {
            if (up) {
                if (this.cursorRow === this.keyboardRows) {
                    this.cursorRow = this.keyboardRows - 1;

                    if (this.cursorColumn % 2) {
                        this.cursorColumn = this.keyboardColumns - 1;
                    }
                    else {
                        this.cursorColumn = 0;
                    }
                }
                else {
                    this.cursorRow = Math.max(0, this.cursorRow - 1);
                }
            }
            else {
                this.cursorRow = Math.min(this.keyboardRows, this.cursorRow + 1);

                if (this.cursorRow === this.keyboardRows) {
                    // Go to closest button
                    this.cursorColumn = this.cursorColumn > 5 ? 1 : 0;
                }
            }
        }

        protected moveHorizontal(right: boolean) {
            if (right) {
                this.cursorColumn = (this.cursorColumn + 1) % this.keyboardColumns;
            }
            else {
                this.cursorColumn = (this.cursorColumn + (this.keyboardColumns - 1)) % this.keyboardColumns;
            }
        }

        protected confirm() {
            if (this.cursorRow === 3) {
                if (this.cursorColumn % 2) {
                    this.confirmPressed = true;
                }
                else {
                    this.upper = !this.upper;
                }
            }
            else {
                if (this.selectionStart >= this.answerLength) return;

                const index = this.cursorColumn + this.cursorRow * this.keyboardColumns
                const letter = getCharForIndex(index, this.upper);

                if (!this.result) {
                    this.result = letter;
                }
                else {
                    this.result += letter;
                }

                this.changeTime = game.runtime();

                this.changeInputIndex(1);
            }
        }

        protected delete() {
            if (this.selectionStart <= 0) return;

            this.result = this.result.substr(0, this.result.length - 1);
            this.changeInputIndex(-1);
        }

        protected changeInputIndex(delta: number) {
            this.selectionStart += delta;
            this.selectionEnd = this.selectionStart;
        }

        protected blink() {
            return Math.idiv(game.runtime() - this.changeTime, 500) & 1;
        }
    }

    function getCharForIndex(index: number, upper: boolean) {
        if (index < 26) {
            return String.fromCharCode(index + (upper ? 65 : 97));
        }
        else {
            if (upper) {
                return digitsUpper[index - 26];
            }
            else {
                return "" + (index - 26);
            }
        }
    }
}

game.renderText.ts:
namespace sprites {
    export class RenderText {
        linebreaks: number[];
        font: image.Font;
        height: number;
        width: number;

        constructor(public text: string, maxWidth: number) {
            this.font = image.getFontForText(text);

            this.setMaxWidth(maxWidth);
        }

        draw(canvas: Image, left: number, top: number, color: number, lineStart?: number, lineEnd?: number) {
            if (lineStart === undefined) lineStart = 0;
            if (lineEnd === undefined) lineEnd = this.linebreaks.length + 1;

            for (let i = lineStart; i < lineEnd; i++) {
                this.drawLine(canvas, left, top, i, color);
                top += this.font.charHeight;
            }
        }

        drawLine(canvas: Image, left: number, top: number, lineIndex: number, color: number) {
            const start = this.lineStart(lineIndex);
            const end = this.lineEnd(lineIndex);

            for (let i = start; i < end; i++) {
                canvas.print(this.text.charAt(i), left, top, color, this.font);
                left += this.font.charWidth;
            }
        }

        drawPartial(canvas: Image, left: number, top: number, color: number, lengthToDraw: number, lineStart?: number, lineEnd?: number) {
            if (lineStart === undefined) lineStart = 0;
            if (lineEnd === undefined) lineEnd = this.linebreaks.length + 1;

            let currentTextIndex = 0;
            for (let i = lineStart; i < lineEnd; i++) {
                currentTextIndex = this.drawPartialLine(canvas, left, top, i, color, currentTextIndex, lengthToDraw);
                top += this.font.charHeight;
                if (currentTextIndex >= lengthToDraw) return false;
            }

            return true;
        }

        drawPartialLine(canvas: Image, left: number, top: number, lineIndex: number, color: number, currentTextIndex: number, lengthToDraw: number) {
            const start = this.lineStart(lineIndex);
            const end = this.lineEnd(lineIndex);

            for (let i = start; i < end; i++) {
                canvas.print(this.text.charAt(i), left, top, color, this.font);
                left += this.font.charWidth;

                if (currentTextIndex + (i - start) >= lengthToDraw) {
                    return lengthToDraw;
                }
            }
            return currentTextIndex + end - start;
        }

        calculatePartialHeight(startLine: number, lengthToDraw: number) {
            if (this.linebreaks.length === 0) return this.font.charHeight;

            let current = 0;

            for (let i = startLine; i < this.linebreaks.length + 1; i++) {
                current += this.lineEnd(i) - this.lineStart(i);
                if (current > lengthToDraw) return (i - startLine + 1) * this.font.charHeight
            }
            return this.height;
        }

        lineHeight() {
            return this.font.charHeight;
        }

        setMaxWidth(maxWidth: number) {
            this.linebreaks = getLineBreaks(this.text, [Math.idiv(maxWidth, this.font.charWidth)]);
            this.height = (this.linebreaks.length + 1) * this.font.charHeight;

            this.width = 0;
            for (let i = 0; i < this.linebreaks.length + 1; i++) {
                this.width = Math.max(this.lineEnd(i) - this.lineStart(i), this.width);
            }
            this.width *= this.font.charWidth;
        }

        printableCharacters() {
            let total = 0;
            for (let i = 0; i < this.linebreaks.length + 1; i++) {
                total += this.lineEnd(i) - this.lineStart(i);
            }
            return total;
        }

        lineEnd(lineIndex: number) {
            const prevEnd = lineIndex > 0 ? this.linebreaks[lineIndex - 1] : 0;
            let end = lineIndex < this.linebreaks.length ? this.linebreaks[lineIndex] : this.text.length;
            let didMove = false;

            // Trim trailing whitespace
            while (end > prevEnd) {
                if (this.text.charCodeAt(end) <= 32) {
                    end--;
                    didMove = true
                }
                else if (this.text.charAt(end) === "n" && this.text.charAt(end - 1) === "\\" && end - 1 > prevEnd) {
                    end -= 2;
                    didMove = true
                }
                else {
                    break;
                }
            }
            return didMove ? end + 1 : end;
        }

        lineStart(lineIndex: number) {
            let start = lineIndex > 0 ? this.linebreaks[lineIndex - 1] : 0;

            // Trim leading whitespace
            while (start < this.text.length) {
                if (this.text.charCodeAt(start) <= 32) {
                    start ++;
                }
                else if (this.text.charAt(start) === "\\" && this.text.charAt(start + 1) === "n" && start + 1 < this.text.length) {
                    start += 2;
                }
                else {
                    break;
                }
            }

            return start;
        }

        widthOfLine(lineIndex: number, fullTextOffset?: number) {
            if (fullTextOffset != undefined) {
                return (Math.min(this.lineEnd(lineIndex), fullTextOffset + 1) - this.lineStart(lineIndex)) * this.font.charWidth;
            }
            return (this.lineEnd(lineIndex) - this.lineStart(lineIndex)) * this.font.charWidth;
        }

        widthOfLines(lineStartIndex: number, lineEndIndex: number, offset?: number) {
            if (this.linebreaks.length === 0) return this.widthOfLine(0, offset);

            let width = 0;
            let fullTextOffset: number;
            for (let i = lineStartIndex; i < Math.min(lineEndIndex, this.linebreaks.length + 1); i++) {
                if (offset != undefined) {
                    fullTextOffset = this.lineStart(i) + offset;
                    offset -= this.lineEnd(i) - this.lineStart(i);
                }
                if (fullTextOffset !== undefined && this.lineStart(i) > fullTextOffset) break;
                width = Math.max(width, this.widthOfLine(i, fullTextOffset));
            }
            return width;
        }
    }


    function isBreakCharacter(charCode: number) {
        return charCode <= 32 ||
            (charCode >= 58 && charCode <= 64) ||
            (charCode >= 91 && charCode <= 96) ||
            (charCode >= 123 && charCode <= 126);
    }

    function getLineBreaks(text: string, lineLengths: number[]): number[] {
        const result: number[] = [];

        let lastBreakLocation = 0;
        let lastBreak = 0;
        let line = 0;
        let lineLength = lineLengths[line];

        function nextLine() {
            line++;
            lineLength = lineLengths[line % lineLengths.length];
        }

        for (let index = 0; index < text.length; index++) {
            if (text.charAt(index) === "\n") {
                result.push(index);
                index++;
                lastBreak = index;
                nextLine();
            }
            // Handle \\n in addition to \n because that's how it gets converted from blocks
            else if (text.charAt(index) === "\\" && text.charAt(index + 1) === "n") {
                result.push(index);
                lastBreak = index;
                index += 2;
                nextLine();
            }
            else if (isBreakCharacter(text.charCodeAt(index))) {
                lastBreakLocation = index;
            }

            if (index - lastBreak === lineLength) {
                if (lastBreakLocation === index || lastBreakLocation <= lastBreak) {
                    result.push(index);
                    lastBreak = index;
                    nextLine();
                }
                else {
                    result.push(lastBreakLocation);
                    lastBreak = lastBreakLocation;
                    nextLine();
                }
            }
        }

        return result;
    }

    enum RenderTextAnimationState {
        Idle,
        Printing,
        Pausing
    }

    export class RenderTextAnimation {
        protected tickPeriod: number;
        protected state: RenderTextAnimationState;
        protected pageLine: number;
        protected timer: number;
        protected pauseMillis: number;
        protected onTickCB: () => void;
        protected onEndCB: () => void;
        protected prevOffset: number;

        constructor(public text: RenderText, public height: number) {
            this.state = RenderTextAnimationState.Idle;
            this.timer = -1;

            this.pageLine = 0;
            this.setPauseLength(1000);
            this.setTextSpeed(30);
        }

        start() {
            this.state = RenderTextAnimationState.Printing;
            this.timer = control.millis();
        }

        numPages() {
            const maxLinesPerPage =  Math.idiv(this.height, this.text.lineHeight()) + 1;
            return Math.floor((this.text.linebreaks.length + 1) / maxLinesPerPage);
        }

        setPauseLength(millis: number) {
            this.pauseMillis = millis;
        }

        setTextSpeed(charactersPerSecond: number) {
            this.tickPeriod = 1000/ charactersPerSecond;
        }

        currentHeight() {
            const minHeight = this.text.lineHeight();
            const maxHeight = Math.max(
                Math.min(
                    Math.idiv(this.height, this.text.lineHeight()) + 1,
                    this.text.linebreaks.length + 1 - this.pageLine
                ) * this.text.lineHeight(),
                minHeight
            );


            if (this.state === RenderTextAnimationState.Printing) {
                return Math.max(Math.min(
                    this.text.calculatePartialHeight(this.pageLine, this.currentOffset()),
                    maxHeight
                ), minHeight)
            }
            else if (this.state === RenderTextAnimationState.Pausing) {
                return maxHeight
            }
            else {
                return 0;
            }
        }

        currentWidth() {
            return this.text.widthOfLines(
                this.pageLine,
                this.pageLine + Math.idiv(this.currentHeight(), this.text.lineHeight()) + 1,
                this.state === RenderTextAnimationState.Printing ? this.currentOffset() : undefined
            );
        }

        currentOffset() {
            return Math.idiv(control.millis() - this.timer, this.tickPeriod)
        }

        isDone() {
            return this.state === RenderTextAnimationState.Idle;
        }

        cancel() {
            this.state = RenderTextAnimationState.Idle;
        }

        onCharacterPrinted(cb: () => void) {
            this.onTickCB = cb;
        }

        onAnimationEnd(cb: () => void) {
            this.onEndCB = cb;
        }

        draw(canvas: Image, left: number, top: number, color: number) {
            if (this.state === RenderTextAnimationState.Idle) return;
            else if (this.state === RenderTextAnimationState.Printing) {
                const pageFinished = this.text.drawPartial(
                    canvas,
                    left,
                    top,
                    color,
                    this.currentOffset(),
                    this.pageLine,
                    this.pageLine + Math.idiv(this.height, this.text.lineHeight()) + 1
                );

                if (this.onTickCB && this.prevOffset !== this.currentOffset()) {
                    this.onTickCB();
                }

                if (pageFinished) {
                    this.state = RenderTextAnimationState.Pausing;
                    this.timer = this.pauseMillis
                }
            }
            else {
                this.text.draw(
                    canvas,
                    left,
                    top,
                    color,
                    this.pageLine,
                    this.pageLine + Math.idiv(this.height, this.text.lineHeight()) + 1
                );

                this.timer -= game.currentScene().eventContext.deltaTimeMillis;

                if (this.timer < 0) {
                    this.pageLine += Math.idiv(this.height, this.text.lineHeight()) + 1;
                    if (this.pageLine > this.text.linebreaks.length) {
                        this.state = RenderTextAnimationState.Idle;
                        if (this.onEndCB) this.onEndCB();
                    }
                    else {
                        this.state = RenderTextAnimationState.Printing;
                        this.timer = control.millis();
                    }
                }
            }

            this.prevOffset = this.currentOffset();
        }
    }
}

game.renderable.ts:
namespace scene {
    export class Renderable extends sprites.BaseSprite {
        public constructor(
            protected handler: (target: Image, camera: Camera) => void,
            protected shouldBeVisible: () => boolean,
            z: number,
        ) {
            super(z);
        }

        __visible(): boolean {
            return this.shouldBeVisible();
        }

        __drawCore(camera: scene.Camera) {
            this.handler(screen, camera);
        }

        destroy() {
            const s = game.currentScene();
            s.allSprites.removeElement(this);
        }
    }

    export function createRenderable(
        z: number,
        handler: (target: Image, camera: Camera) => void,
        shouldBeVisible?: () => boolean
    ): Renderable {
        const renderable = new Renderable(
            handler,
            shouldBeVisible || (() => true),
            z,
        );

        return renderable;
    }
}

game.rotation.ts:
namespace sprites {
    let aabbPoints: number[];

    export class RotatedBoundingBox {
        protected _rotation: number;
        protected _width: number;
        protected _height: number;

        protected points: number[];
        protected cornerDistance: number;
        protected cornerAngle: number;

        public get x0(): number {
            return this.points[0];
        }

        public get y0(): number {
            return this.points[1];
        }

        public get x1(): number {
            return this.points[2];
        }

        public get y1(): number {
            return this.points[3];
        }

        public get x2(): number {
            return this.points[4];
        }

        public get y2(): number {
            return this.points[5];
        }

        public get x3(): number {
            return this.points[6];
        }

        public get y3(): number {
            return this.points[7];
        }

        public get rotation() {
            return this._rotation;
        }

        public set rotation(value: number) {
            this.setRotation(value);
        }

        public get width() {
            return this._width;
        }

        public get height() {
            return this._height;
        }

        constructor(
            public anchor: Sprite,
            width: number,
            height: number
        ) {
            this.points = [];
            this._rotation = 0;
            this.setDimensions(width, height);
        }

        setDimensions(width: number, height: number) {
            width /= 2;
            height /= 2;

            this.cornerDistance = Math.sqrt(
                width * width + height * height
            );
            this.cornerAngle = Math.atan2(height, width);
            this.setRotation(this._rotation);
        }

        setRotation(angle: number) {
            this._rotation = angle;
            this.points[0] = Math.cos(this.cornerAngle + angle) * this.cornerDistance;
            this.points[1] = Math.sin(this.cornerAngle + angle) * this.cornerDistance;
            this.points[2] = Math.cos(Math.PI - this.cornerAngle + angle) * this.cornerDistance;
            this.points[3] = Math.sin(Math.PI - this.cornerAngle + angle) * this.cornerDistance;
            this.points[4] = Math.cos(Math.PI + this.cornerAngle + angle) * this.cornerDistance;
            this.points[5] = Math.sin(Math.PI + this.cornerAngle + angle) * this.cornerDistance;
            this.points[6] = Math.cos(angle - this.cornerAngle) * this.cornerDistance;
            this.points[7] = Math.sin(angle - this.cornerAngle) * this.cornerDistance;
            this.updateWidthHeight();
        }

        overlaps(other: RotatedBoundingBox): boolean {
            return doRectanglesIntersect(
                this.points,
                this.anchor.x,
                this.anchor.y,
                other.points,
                other.anchor.x,
                other.anchor.y
            );
        }

        overlapsAABB(left: number, top: number, right: number, bottom: number) {
            if (!aabbPoints) {
                aabbPoints = [];
            }

            aabbPoints[0] = left;
            aabbPoints[1] = top;
            aabbPoints[2] = right;
            aabbPoints[3] = top;
            aabbPoints[4] = right;
            aabbPoints[5] = bottom;
            aabbPoints[6] = left;
            aabbPoints[7] = bottom;
            return doRectanglesIntersect(
                this.points,
                this.anchor.x,
                this.anchor.y,
                aabbPoints,
                0,
                0
            );
        }

        protected updateWidthHeight() {
            let minX = this.points[0];
            let maxX = minX;
            let minY = this.points[1];
            let maxY = minY;

            for (let i = 2; i < 8; i += 2) {
                minX = Math.min(minX, this.points[i]);
                maxX = Math.max(maxX, this.points[i]);
                minY = Math.min(minY, this.points[i + 1]);
                maxY = Math.max(maxY, this.points[i + 1]);
            }

            this._width = (maxX - minX) | 0;
            this._height = (maxY - minY) | 0;
        }
    }

    // adapted from https://stackoverflow.com/questions/10962379/how-to-check-intersection-between-2-rotated-rectangles
    // but optimized for rectangles
    function doRectanglesIntersect(a: number[], ax: number, ay: number, b: number[], bx: number, by: number) {
        return !(checkForNonIntersection(a, ax, ay, b, bx, by) || checkForNonIntersection(b, bx, by, a, ax, ay));
    }

    function checkForNonIntersection(a: number[], ax: number, ay: number, b: number[], bx: number, by: number) {
        // we only need to check the first two sides because the
        // normals are the same for the other two
        for (let pointIndex = 0; pointIndex < 4; pointIndex += 2) {
            const normalX = a[pointIndex + 3] - a[pointIndex + 1];
            const normalY = a[pointIndex] - a[pointIndex + 2];

            let minA: number = undefined;
            let maxA: number = undefined;
            let minB: number = undefined;
            let maxB: number = undefined;

            for (let i = 0; i < 8; i += 2) {
                const projected = normalX * (a[i] + ax) + normalY * (a[i + 1] + ay);

                if (minA === undefined || projected < minA) {
                    minA = projected;
                }
                if (maxA == undefined || projected > maxA) {
                    maxA = projected;
                }
            }

            for (let i = 0; i < 8; i += 2) {
                const projected = normalX * (b[i] + bx) + normalY * (b[i + 1] + by);

                if (minB === undefined || projected < minB) {
                    minB = projected;
                }
                if (maxB == undefined || projected > maxB) {
                    maxB = projected;
                }
            }

            if (maxA < minB || maxB < minA) {
                return true;
            }
        }

        return false;
    }
}

game.scene.ts:
interface SparseArray<T> {
    [index: number]: T;
}

/**
 * Control the background, tiles and camera
 */
namespace scene {
    export enum Flag {
        NeedsSorting = 1 << 0, // indicates the sprites in the scene need to be sorted before rendering
        SeeThrough = 1 << 1, // if set, render the previous scene 'below' this one as the background
        IsRendering = 1 << 2, // if set, the scene is currently being rendered to the screen
    }

    export class SpriteHandler {
        constructor(
            public kind: number,
            public handler: (sprite: Sprite) => void
        ) { }
    }

    export class OverlapHandler {
        constructor(
            public kind: number,
            public otherKind: number,
            public handler: (sprite: Sprite, otherSprite: Sprite) => void
        ) { }
    }

    export class TileWallHandler {
        constructor(
            public spriteKind: number,
            public handler: (sprite: Sprite, location: tiles.Location) => void
        ) { }
    }

    export class TileOverlapHandler {
        constructor(
            public spriteKind: number,
            public tileKind: Image,
            public handler: (sprite: Sprite, location: tiles.Location) => void
        ) { }
    }


    export class GameForeverHandler {
        public lock: boolean;
        constructor(
            public handler: () => void
        ) { }
    }

    // frame handler priorities
    export const CONTROLLER_PRIORITY = 8;
    export const UPDATE_CONTROLLER_PRIORITY = 13;
    export const FOLLOW_SPRITE_PRIORITY = 14;
    export const PHYSICS_PRIORITY = 15;
    export const ANIMATION_UPDATE_PRIORITY = 15;
    export const CONTROLLER_SPRITES_PRIORITY = 13;
    export const UPDATE_INTERVAL_PRIORITY = 19;
    export const UPDATE_PRIORITY = 20;
    export const PRE_RENDER_UPDATE_PRIORITY = 55;
    export const RENDER_BACKGROUND_PRIORITY = 60;
    export const RENDER_SPRITES_PRIORITY = 90;
    export const RENDER_DIAGNOSTICS_PRIORITY = 150;
    export const MULTIPLAYER_SCREEN_PRIORITY = 190;
    export const UPDATE_SCREEN_PRIORITY = 200;
    export const MULTIPLAYER_POST_SCREEN_PRIORITY = 210;

    // default rendering z indices
    export const ON_PAINT_Z = -20;
    export const TILE_MAP_Z = -1;
    export const SPRITE_Z = 0;
    export const ON_SHADE_Z = 80;
    export const HUD_Z = 100;

    export class Scene {
        eventContext: control.EventContext;
        background: Background;
        tileMap: tiles.TileMap;
        allSprites: SpriteLike[];
        private spriteNextId: number;
        spritesByKind: SparseArray<sprites.SpriteSet>;
        physicsEngine: PhysicsEngine;
        camera: scene.Camera;
        flags: number;
        destroyedHandlers: SpriteHandler[];
        createdHandlers: SpriteHandler[];
        overlapHandlers: OverlapHandler[];
        overlapMap: SparseArray<number[]>;
        tileOverlapHandlers: TileOverlapHandler[];
        collisionHandlers: SpriteHandler[][];
        wallCollisionHandlers: TileWallHandler[];
        gameForeverHandlers: GameForeverHandler[];
        particleSources: particles.ParticleSource[];
        controlledSprites: controller.ControlledSprite[][];
        controllerConnectionState: boolean[]
        followingSprites: sprites.FollowingSprite[];
        buttonEventHandlers: controller.ButtonEventHandlerState[];

        private _millis: number;
        private _data: any;

        // a set of functions that need to be called when a scene is being initialized
        static initializers: ((scene: Scene) => void)[] = [];

        constructor(eventContext: control.EventContext, protected previousScene?: Scene) {
            this.eventContext = eventContext;
            this.flags = 0;
            this.physicsEngine = new ArcadePhysicsEngine();
            this.camera = new scene.Camera();
            this.background = new Background(this.camera);
            this.destroyedHandlers = [];
            this.createdHandlers = [];
            this.overlapHandlers = [];
            this.overlapMap = {};
            this.tileOverlapHandlers = [];
            this.collisionHandlers = [];
            this.wallCollisionHandlers = [];
            this.gameForeverHandlers = [];
            this.spritesByKind = {};
            this.controlledSprites = [];
            this.buttonEventHandlers = [];
            this._data = {};
            this._millis = 0;
        }

        init() {
            if (this.allSprites) return;

            power.poke(); // keep game alive a little more
            this.allSprites = [];
            this.spriteNextId = 0;
            // update controller state
            this.eventContext.registerFrameHandler(CONTROLLER_PRIORITY, () => {
                this._millis += this.eventContext.deltaTimeMillis;
                control.enablePerfCounter("controller_update")
                controller.__update(this.eventContext.deltaTime);
            })
            // controller update 13
            this.eventContext.registerFrameHandler(CONTROLLER_SPRITES_PRIORITY, controller._moveSprites);
            // sprite following 14
            // apply physics and collisions 15
            this.eventContext.registerFrameHandler(PHYSICS_PRIORITY, () => {
                control.enablePerfCounter("physics and collisions")
                this.physicsEngine.move(this.eventContext.deltaTime);
            });
            // user update interval 19s

            // user update 20

            // prerender update 55
            this.eventContext.registerFrameHandler(PRE_RENDER_UPDATE_PRIORITY, () => {
                const dt = this.eventContext.deltaTime;
                this.camera.update();

                for (const s of this.allSprites)
                    s.__update(this.camera, dt);
            })

            // render background 60

            // render 90
            this.eventContext.registerFrameHandler(RENDER_SPRITES_PRIORITY, () => {
                control.enablePerfCounter("scene_draw");
                this.render();
            });
            // render diagnostics
            this.eventContext.registerFrameHandler(RENDER_DIAGNOSTICS_PRIORITY, () => {
                if (game.stats && control.EventContext.onStats) {
                    control.EventContext.onStats(
                        control.EventContext.lastStats +
                        ` sprites:${this.allSprites.length}`
                    )
                }
                if (game.debug)
                    this.physicsEngine.draw();
                game.consoleOverlay.draw();
                // check for power deep sleep
                power.checkDeepSleep();
            });
            // update screen
            this.eventContext.registerFrameHandler(UPDATE_SCREEN_PRIORITY, control.__screen.update);
            multiplayer.initServer();
            multiplayer.initPlayerConnectionListeners();
            // register additional components
            Scene.initializers.forEach(f => f(this));
        }

        get data() {
            return this._data;
        }

        /**
         * Gets the elapsed time in the scene
         */
        millis(): number {
            return this._millis;
        }

        addSprite(sprite: SpriteLike) {
            this.allSprites.push(sprite);
            sprite.id = this.spriteNextId++;
        }

        destroy() {
            this.eventContext = undefined;
            this.background = undefined;
            this.tileMap = undefined;
            this.allSprites = undefined;
            this.spriteNextId = undefined;
            this.spritesByKind = undefined;
            this.physicsEngine = undefined;
            this.camera = undefined;
            this.flags = undefined;
            this.destroyedHandlers = undefined;
            this.createdHandlers = undefined;
            this.overlapHandlers = undefined;
            this.tileOverlapHandlers = undefined;
            this.collisionHandlers = undefined;
            this.wallCollisionHandlers = undefined;
            this.gameForeverHandlers = undefined;
            this._data = undefined;
        }

        /**
         * Renders the current frame as an image
         */
        render() {
            // bail out from recursive or parallel call.
            if (this.flags & scene.Flag.IsRendering) return;
            this.flags |= scene.Flag.IsRendering;

            control.enablePerfCounter("render background")
            if ((this.flags & scene.Flag.SeeThrough) && this.previousScene) {
                this.previousScene.render();
            } else {
                this.background.draw();
            }

            control.enablePerfCounter("sprite sort")
            if (this.flags & Flag.NeedsSorting) {
                this.allSprites.sort(function (a, b) { return a.z - b.z || a.id - b.id; })
                this.flags &= ~scene.Flag.NeedsSorting;
            }

            control.enablePerfCounter("sprite draw")
            for (const s of this.allSprites) {
                s.__draw(this.camera);
            }

            this.flags &= ~scene.Flag.IsRendering;
        }
    }
}

game.scenes.ts:
/**
 * Control the background, tiles and camera
 */

enum CameraProperty {
    //% block="x"
    X,
    //% block="y"
    Y,
    //% block="left"
    Left,
    //% block="right"
    Right,
    //% block="top"
    Top,
    //% block="bottom"
    Bottom
}

//% weight=88 color="#4b6584" icon="\uf1bb"
//% groups='["Screen", "Camera", "Effects", "Tilemaps", "Tilemap Operations", "Locations"]'
//% blockGap=8
namespace scene {
    /**
     * Get the width of the screen in pixels
     */
    //% blockId=scenescreenwidth block="screen width"
    //% group="Screen"
    //% weight=100 blockGap=8
    //% help=scene/screen-width
    export function screenWidth(): number {
        return screen.width;
    }

    /**
     * Gets the height of the screen in pixels
     */
    //% blockId=scenescreenheight block="screen height"
    //% group="Screen"
    //% weight=99
    //% help=scene/screen-width
    export function screenHeight(): number {
        return screen.height;
    }

    /**
     * Set the game background color
     * @param color
     */
    //% group="Screen"
    //% weight=25
    //% blockId=gamesetbackgroundcolor block="set background color to %color=colorindexpicker"
    //% help=scene/set-background-color
    export function setBackgroundColor(color: number) {
        const scene = game.currentScene();
        scene.background.color = color;
    }

    /**
     * Get the game background color
     * @param color
     */
    //% group="Screen"
    //% weight=22
    //% blockId=gamebackgroundcolor block="background color"
    //% help=scene/background-color
    export function backgroundColor() : number {
        const scene = game.currentScene();
        return scene.background.color;
    }

    /**
     * Set a picture as the background
     */
    //% group="Screen"
    //% weight=24
    //% blockId=gamesetbackgroundimage block="set background image to %img=background_image_picker"
    //% help=scene/set-background-image
    export function setBackgroundImage(img: Image) {
        const scene = game.currentScene();
        scene.background.image = img;
    }

    /**
     * Get the current background image
     */
    //% weight=22
    //% group="Screen"
    //% blockId=gamebackgroundimage block="background image"
    //% help=scene/background-image
    export function backgroundImage(): Image {
        const scene = game.currentScene();
        return scene.background.image;
    }

    /**
     * Adds a moving background layer
     * @param distance distance of the layer which determines how fast it moves, eg: 10
     * @param img
     */
    //% group="Screen"
    //% weight=10
    export function addBackgroundLayer(image: Image, distance?: number, alignment?: BackgroundAlignment) {
        const scene = game.currentScene();
        if (image)
            scene.background.addLayer(image, distance || 100, alignment || BackgroundAlignment.Bottom);
    }

    /**
     * Set the map for placing tiles in the scene
     * @param map
     * @param scale
     */
    export function setTileMapLevel(map: tiles.TileMapData) {
        const scene = game.currentScene();
        if (!scene.tileMap)
            scene.tileMap = new tiles.TileMap();
        scene.tileMap.setData(map);
    }

     /**
     * Shake the camera
     * @param sprite
     */
    //% blockId=camerashake block="camera shake by %amplitude pixels for %duration ms"
    //% amplitude.min=1 amplitude.max=8 amplitude.defl=4
    //% duration.shadow=timePicker duration.defl=500
    //% group="Camera"
    //% help=scene/camera-shake
    //% weight=90
    export function cameraShake(amplitude: number = 4, duration: number = 500) {
        const scene = game.currentScene();
        scene.camera.shake(amplitude, duration);
    }

    /**
     * Set the game camera to follow a sprite
     * @param sprite
     */
    //% blockId=camerafollow block="camera follow sprite %sprite=variables_get(mySprite)"
    //% group="Camera"
    //% sprite.defl=mySprite
    //% help=scene/camera-follow-sprite
    //% weight=100
    export function cameraFollowSprite(sprite: Sprite) {
        const scene = game.currentScene();
        scene.camera.sprite = sprite;
        scene.camera.update();
    }

    /**
     * Moves the camera center to a coordinate position
     * @param sprite
     */
    //% blockId=camerapos block="center camera at x %x y %y"
    //% group="Camera"
    //% help=scene/center-camera-at
    //% weight=80
    export function centerCameraAt(x: number, y: number) {
        const scene = game.currentScene();
        scene.camera.sprite = undefined;
        scene.camera.offsetX = x - (screen.width >> 1);
        scene.camera.offsetY = y - (screen.height >> 1);
    }

    /**
     * Returns the x coordinate of the camera (the left of the screen)
     */
    //% blockId=cameraleft block="camera left"
    //% group="Camera"
    //% help=scene/camera-left
    //% deprecated=true
    export function cameraLeft() {
        const scene = game.currentScene();
        return scene.camera.drawOffsetX;
    }

    /**
     * Returns the y coordinate of the camera (the top of the screen)
     */
    //% blockId=cameratop block="camera top"
    //% group="Camera"
    //% help=scene/camera-top
    //% deprecated=true
    export function cameraTop() {
        const scene = game.currentScene();
        return scene.camera.drawOffsetY;
    }

    /**
     * Returns the specified camera property
     * @param property The property to get
     */
    //% blockId=cameraproperty block="camera $property"
    //% group="Camera"
    //% help=scene/camera-property
    //% weight=70
    export function cameraProperty(property: CameraProperty): number {
        const scene = game.currentScene();
        if (!scene.camera.isUpdated())
            scene.camera.update();
        switch (property) {
            case CameraProperty.X: return scene.camera.x;
            case CameraProperty.Y: return scene.camera.y;
            case CameraProperty.Left: return scene.camera.left;
            case CameraProperty.Right: return scene.camera.right;
            case CameraProperty.Top: return scene.camera.top;
            case CameraProperty.Bottom: return scene.camera.bottom;
        }
    }
}

