mixer---rp2040.playable.ts:
namespace music {
    export enum PlaybackMode {
        //% block="until done"
        UntilDone,
        //% block="in background"
        InBackground,
        //% block="looping in background"
        LoopingInBackground
    }

    let stateStack: PlayableState[];

    class PlayableState {
        looping: Playable[];
        constructor() {
            this.looping = [];
        }

        stopLooping() {
            for (const p of this.looping) {
                p.stopped = true;
            }
            this.looping = [];
        }
    }

    function state() {
        _init();
        return stateStack[stateStack.length - 1];
    }

    function _init() {
        if (stateStack) return;
        stateStack = [new PlayableState()];
    }

    export function _initializeSceneStack(addScenePushHandler: (handler: () => void) => void, addScenePopHandler: (handler: () => void) => void) {
        _init();

        addScenePushHandler(() => {
            stateStack.push(new PlayableState());
        });

        addScenePopHandler(() => {
            stateStack.pop();
            if (stateStack.length === 0) stateStack.push(new PlayableState());
        });
    }

    export class Playable {
        stopped: boolean;
        constructor() {

        }

        play(playbackMode: PlaybackMode) {
            // subclass
        }

        loop() {
            state().looping.push(this);
            this.stopped = false;

            control.runInParallel(() => {
                while (!this.stopped) {
                    this.play(PlaybackMode.UntilDone);
                }
            });
        }
    }

    export class MelodyPlayable extends Playable {
        constructor(public melody: Melody) {
            super();
        }

        play(playbackMode: PlaybackMode) {
            if (playbackMode === PlaybackMode.InBackground) {
                this.melody.play(music.volume());
            }
            else if (playbackMode === PlaybackMode.UntilDone) {
                this.melody.playUntilDone(music.volume());
            }
            else {
                this.melody.loop(music.volume());
            }
        }
    }

    export class TonePlayable extends Playable {
        constructor(public pitch: number, public duration: number) {
            super();
        }

        play(playbackMode: PlaybackMode) {
            if (playbackMode === PlaybackMode.InBackground) {
                control.runInParallel(() => music.playTone(this.pitch, this.duration));
            }
            else if (playbackMode === PlaybackMode.UntilDone) {
                music.playTone(this.pitch, this.duration);
                if (this.duration > 2000) {
                    pause(this.duration);
                }
            }
            else {
                this.loop();
            }
        }
    }

    /**
     * Play a song, melody, or other sound. The music plays until finished or can play as a
     * background task.
     * @param toPlay the song or melody to play
     * @param playbackMode play the song or melody until it's finished or as background task
     */
    //% blockId="music_playable_play"
    //% block="play $toPlay $playbackMode"
    //% toPlay.shadow=music_melody_playable
    //% group="Sounds"
    //% help="music/play"
    export function play(toPlay: Playable, playbackMode: PlaybackMode) {
        toPlay.play(playbackMode);
    }

    /**
     * Create a Playable object for a melody.
     * @param melody the melody to make playable
     */
    //% blockId="music_melody_playable"
    //% block="sound $melody"
    //% toolboxParent=music_playable_play
    //% toolboxParentArgument=toPlay
    //% group="Sounds"
    //% duplicateShadowOnDrag
    //% blockHidden
    //% help=music/melody-playable
    export function melodyPlayable(melody: Melody): Playable {
        return new MelodyPlayable(melody);
    }

    /**
     * Create a Playable object for a melody string containg notes.
     * @param melody the melody string to make playable
     */
    //% blockId="music_string_playable"
    //% block="melody $melody at tempo $tempo|(bpm)"
    //% toolboxParent=music_playable_play
    //% toolboxParentArgument=toPlay
    //% weight=85 blockGap=8
    //% help=music/melody-editor
    //% group="Songs"
    //% duplicateShadowOnDrag
    //% melody.shadow=melody_editor
    //% tempo.min=40 tempo.max=500
    //% tempo.defl=120
    //% help=music/string-playable
    export function stringPlayable(melody: string, tempo: number): Playable {
        let notes: string[] = melody.split(" ").filter(n => !!n);
        let formattedMelody = "";
        let newOctave = false;

        // build melody string, replace '-' with 'R' and add tempo
        // creates format like "C5-174 B4 A G F E D C "
        for (let i = 0; i < notes.length; i++) {
            if (notes[i] === "-") {
                notes[i] = "R";
            } else if (notes[i] === "C5") {
                newOctave = true;
            } else if (newOctave) { // change the octave if necesary
                notes[i] += "4";
                newOctave = false;
            }
            // add tempo after first note
            if (i == 0) {
                formattedMelody += notes[i] + "-" + tempo + " ";
            } else {
                formattedMelody += notes[i] + " ";
            }
        }

        return new MelodyPlayable(new Melody(formattedMelody));
    }

    /**
     * Create a Playable object for a single tone and its duration.
     * @param note the note or tone frequency to play
     * @param duration the duration of the tone in milliseconds (ms)
     */
    //% blockId="music_tone_playable"
    //% block="tone $note for $duration"
    //% toolboxParent=music_playable_play
    //% toolboxParentArgument=toPlay
    //% group="Tone"
    //% duplicateShadowOnDrag
    //% note.shadow=device_note
    //% duration.shadow=device_beat
    //% parts="headphone"
    //% help=music/tone-playable
    export function tonePlayable(note: number, duration: number): Playable {
        return new TonePlayable(note, duration);
    }

    export function _stopPlayables() {
        state().stopLooping();
    }
}

mixer---rp2040.sequencer.ts:
namespace music.sequencer {
    const SEQUENCER_STOP_MESSAGE = 3243;
    const SEQUENCER_TICK_MESSAGE = 3244;
    const SEQUENCER_STATE_CHANGE_MESSAGE = 3245;
    const SEQUENCER_LOOPED_MESSAGE = 3246;

    export class Sequencer {
        currentTick: number;
        isPlaying: boolean;
        isLooping: boolean;
        isRunning: boolean;

        constructor(public song: Song) {
            this.currentTick = 0;
            this.isPlaying = false;
            this.isLooping = false;
        }

        start(loop: boolean) {
            this.currentTick = 0;
            this.isLooping = loop;
            this.isPlaying = true;

            if (this.isRunning) return;
            this.isRunning = true;

            control.runInParallel(() => {
                while (this.isPlaying) {
                    this.scheduleCurrentTick();

                    this.currentTick ++;

                    if (this.currentTick >= this.song.beatsPerMeasure * this.song.measures * this.song.ticksPerBeat) {
                        if (this.isLooping) this.currentTick = 0;
                        else this.isPlaying = false;
                    }

                    pause(this.tickToMs(1))
                }
                this.isRunning = false;
            })
        }

        stop() {
            this.isPlaying = false;
        }

        tickToMs(ticks: number) {
            return ((60000 / this.song.beatsPerMinute) / this.song.ticksPerBeat) * ticks;
        }

        protected scheduleCurrentTick() {
            for (const track of this.song.tracks) {
                if (track.currentNoteEvent.startTick === this.currentTick) {
                    if (track.isMelodicTrack) {
                        this.scheduleMelodicTrack(track as MelodicTrack);
                    }
                    else {
                        this.scheduleDrumTrack(track as DrumTrack);
                    }

                    track.advanceNoteEvent();
                }
            }
        }

        protected scheduleMelodicTrack(track: MelodicTrack) {
            for (let i = 0; i < track.currentNoteEvent.polyphony; i++) {
                playInstructions(
                    0,
                    renderInstrument(
                        track.instrument,
                        lookupFrequency(track.currentNoteEvent.getNote(i, track.instrument.octave)),
                        this.tickToMs(track.currentNoteEvent.endTick - track.currentNoteEvent.startTick),
                        music.volume()
                    )
                );
            }
        }

        protected scheduleDrumTrack(track: DrumTrack) {
            for (let i = 0; i < track.currentNoteEvent.polyphony; i++) {
                playInstructions(
                    0,
                    renderDrumInstrument(
                        track.drums[track.currentNoteEvent.getNote(i, undefined)],
                        music.volume()
                    )
                );
            }
        }
    }

    let activeSimSequencers: _SimulatorSequencer[];
    export function _stopAllSimSequencers() {
        if (activeSimSequencers) {
            for (const seq of activeSimSequencers) {
                seq.stop();
                seq.dispose();
            }
            activeSimSequencers = [];
        }
    }

    // Simulator only! Does nothing on hardware
    export class _SimulatorSequencer {
        protected id: number;

        constructor() {
            if (!activeSimSequencers) activeSimSequencers = [];
            activeSimSequencers.push(this);
            this.id = _createSequencer();
            this.setVolume(music.volume());
        }

        play(song: Buffer, loop: boolean) {
            this.setVolume(music.volume());
            _sequencerPlaySong(this.id, song, loop)
        }

        stop() {
            _sequencerStop(this.id);
        }

        setVolume(volume: number) {
            _sequencerSetVolume(this.id, volume);
        }

        setTrackVolume(trackIndex: number, volume: number) {
            _sequencerSetTrackVolume(this.id, trackIndex, volume)
        }

        setDrumTrackVolume(trackIndex: number, drumIndex: number, volume: number) {
            _sequencerSetDrumTrackVolume(this.id, drumIndex, trackIndex, volume)
        }

        state() {
            return _sequencerState(this.id) || "stop";
        }

        currentTick() {
            return _sequencerCurrentTick(this.id);
        }

        dispose() {
            _sequencerDispose(this.id);
        }

        onTick(handler: (tick: number) => void) {
            control.onEvent(SEQUENCER_TICK_MESSAGE, this.id, () => {
                handler(this.currentTick());
            });
        }

        onStateChange(handler: (state: string) => void) {
            control.onEvent(SEQUENCER_STATE_CHANGE_MESSAGE, this.id, () => {
                handler(this.state());
            });
        }

        onStop(handler: () => void) {
            control.onEvent(SEQUENCER_STOP_MESSAGE, this.id, () => {
                handler();
            });
        }

        onLooped(handler: () => void) {
            control.onEvent(SEQUENCER_LOOPED_MESSAGE, this.id, () => {
                handler();
            });
        }
    }

    //% promise
    //% shim=music::_createSequencer
    declare function _createSequencer(): number

    //% shim=music::_sequencerState
    declare function _sequencerState(id: number): string;

    //% shim=music::_sequencerCurrentTick
    declare function _sequencerCurrentTick(id: number): number;

    //% shim=music::_sequencerPlaySong
    declare function _sequencerPlaySong(id: number, song: Buffer, loop: boolean): void;

    //% shim=music::_sequencerStop
    declare function _sequencerStop(id: number): void;

    //% shim=music::_sequencerSetVolume
    declare function _sequencerSetVolume(id: number, volume: number): void;

    //% shim=music::_sequencerSetVolumeForAll
    declare function _sequencerSetVolumeForAll(volume: number): void;

    //% shim=music::_sequencerSetTrackVolume
    declare function _sequencerSetTrackVolume(id: number, trackIndex: number, volume: number): void;

    //% shim=music::_sequencerSetDrumTrackVolume
    declare function _sequencerSetDrumTrackVolume(id: number, trackIndex: number, drumIndex: number, volume: number): void;

    //% shim=music::_sequencerDispose
    declare function _sequencerDispose(id: number): void;
}

mixer---rp2040.soundEffect.ts:
enum WaveShape {
    //% block="sine"
    Sine = 0,
    //% block="sawtooth"
    Sawtooth = 1,
    //% block="triangle"
    Triangle = 2,
    //% block="square"
    Square = 3,
    //% block="noise"
    Noise = 4
}

enum InterpolationCurve {
    //% block="linear"
    Linear,
    //% block="curve"
    Curve,
    //% block="logarithmic"
    Logarithmic
}

enum SoundExpressionEffect {
    //% block="none"
    None = 0,
    //% block="vibrato"
    Vibrato = 1,
    //% block="tremolo"
    Tremolo = 2,
    //% block="warble"
    Warble = 3
}

enum SoundExpressionPlayMode {
    //% block="until done"
    UntilDone,
    //% block="in background"
    InBackground
}

namespace music {
    export class SoundEffect extends Playable {
        waveShape: WaveShape;
        startFrequency: number;
        endFrequency: number;
        startVolume: number;
        endVolume: number;
        duration: number;
        effect: SoundExpressionEffect;
        interpolation: InterpolationCurve;

        constructor() {
            super();
            this.waveShape = WaveShape.Sine;
            this.startFrequency = 5000;
            this.endFrequency = 1;
            this.startVolume = 255;
            this.endVolume = 0;
            this.duration = 1000;
            this.effect = SoundExpressionEffect.None;
            this.interpolation = InterpolationCurve.Linear;
        }

        toBuffer(volume?: number) {
            if (volume === undefined) volume = music.volume();

            return soundToInstructionBuffer(
                this.waveShape,
                this.startFrequency,
                this.endFrequency,
                this.startVolume,
                this.endVolume,
                this.duration,
                this.effect,
                this.interpolation,
                20,
                1,
                volume
            );
        }

        play(playbackMode: PlaybackMode) {
            const toPlay = this.toBuffer(music.volume());
            if (playbackMode === PlaybackMode.InBackground) {
                queuePlayInstructions(0, toPlay);
            }
            else if (playbackMode === PlaybackMode.UntilDone) {
                queuePlayInstructions(0, toPlay);
                pause(this.duration)
            }
            else {
                this.loop();
            }
        }
    }


    /**
     * Play a SoundEffect.
     * @param sound the SoundEffect to play
     * @param mode the play mode, play until done or in the background
     */
    //% blockId=soundExpression_playSoundEffect
    //% block="play sound $sound $mode"
    //% weight=30
    //% help=music/play-sound-effect
    //% blockGap=8
    //% group="Sounds"
    //% deprecated=1
    export function playSoundEffect(sound: SoundEffect, mode: SoundExpressionPlayMode) {
        const toPlay = sound.toBuffer(music.volume());

        queuePlayInstructions(0, toPlay);
        if (mode === SoundExpressionPlayMode.UntilDone) {
            pause(sound.duration);
        }
    }

    /**
     * Create a sound expression from a set of sound effect parameters.
     * @param waveShape waveform of the sound effect
     * @param startFrequency starting frequency for the sound effect waveform
     * @param endFrequency ending frequency for the sound effect waveform
     * @param startVolume starting volume of the sound, or starting amplitude
     * @param endVolume ending volume of the sound, or ending amplitude
     * @param duration the amount of time in milliseconds (ms) that sound will play for
     * @param effect the effect to apply to the waveform or volume
     * @param interpolation interpolation method for frequency scaling
     */
    //% blockId=soundExpression_createSoundEffect
    //% help=music/create-sound-effect
    //% block="$waveShape|| start frequency $startFrequency end frequency $endFrequency duration $duration start volume $startVolume end volume $endVolume effect $effect interpolation $interpolation"
    //% waveShape.defl=WaveShape.Sine
    //% waveShape.fieldEditor=soundeffect
    //% waveShape.fieldOptions.useMixerSynthesizer=true
    //% startFrequency.defl=5000
    //% startFrequency.min=0
    //% startFrequency.max=5000
    //% endFrequency.defl=0
    //% endFrequency.min=0
    //% endFrequency.max=5000
    //% startVolume.defl=255
    //% startVolume.min=0
    //% startVolume.max=255
    //% endVolume.defl=0
    //% endVolume.min=0
    //% endVolume.max=255
    //% duration.defl=500
    //% duration.min=1
    //% duration.max=9999
    //% effect.defl=SoundExpressionEffect.None
    //% interpolation.defl=InterpolationCurve.Linear
    //% compileHiddenArguments=true
    //% inlineInputMode="variable"
    //% inlineInputModeLimit=3
    //% expandableArgumentBreaks="3,5"
    //% toolboxParent=music_playable_play
    //% toolboxParentArgument=toPlay
    //% weight=20
    //% group="Sounds"
    //% duplicateShadowOnDrag
    export function createSoundEffect(waveShape: WaveShape, startFrequency: number, endFrequency: number, startVolume: number, endVolume: number, duration: number, effect: SoundExpressionEffect, interpolation: InterpolationCurve): SoundEffect {
        const result = new SoundEffect();

        result.waveShape = waveShape;
        result.startFrequency = startFrequency;
        result.endFrequency = endFrequency;
        result.startVolume = startVolume;
        result.endVolume = endVolume;
        result.duration = duration;
        result.effect = effect;
        result.interpolation = interpolation;

        return result;
    }

    interface Step {
        frequency: number;
        volume: number;
    }

     export function soundToInstructionBuffer(waveShape: WaveShape, startFrequency: number, endFrequency: number, startVolume: number, endVolume: number, duration: number, effect: SoundExpressionEffect, interpolation: InterpolationCurve, fxSteps: number, fxRange: number, globalVolume: number) {
        const steps: Step[] = [];

        // Optimize the simple case
        if (interpolation === InterpolationCurve.Linear && effect === SoundExpressionEffect.None) {
            steps.push({
                frequency: startFrequency,
                volume: (startVolume / 255) * globalVolume,
            })
            steps.push({
                frequency: endFrequency,
                volume: (endVolume / 255) * globalVolume,
            })
        }
        else {

            fxSteps = Math.min(fxSteps, Math.floor(duration / 5))

            const getVolumeAt = (t: number) => ((startVolume + t * (endVolume - startVolume) / duration) / 255) * globalVolume;
            let getFrequencyAt: (t: number) => number;

            switch (interpolation) {
                case InterpolationCurve.Linear:
                    getFrequencyAt = t => startFrequency + t * (endFrequency - startFrequency) / duration;
                    break;
                case InterpolationCurve.Curve:
                    getFrequencyAt = t => startFrequency + (endFrequency - startFrequency) * Math.sin(t / duration * (Math.PI / 2));
                    break;
                case InterpolationCurve.Logarithmic:
                    getFrequencyAt = t => startFrequency + (Math.log(1 + 9 * (t / duration)) / Math.log(10)) * (endFrequency - startFrequency)
                    break;
            }

            const timeSlice = duration / fxSteps;

            for (let i = 0; i < fxSteps; i++) {
                const newStep = {
                    frequency: getFrequencyAt(i * timeSlice),
                    volume: getVolumeAt(i * timeSlice)
                };

                if (effect === SoundExpressionEffect.Tremolo) {
                    if (i % 2 === 0) {
                        newStep.volume = Math.max(newStep.volume - fxRange * 500, 0)
                    }
                    else {
                        newStep.volume = Math.min(newStep.volume + fxRange * 500, 1023)
                    }
                }
                else if (effect === SoundExpressionEffect.Vibrato) {
                    if (i % 2 === 0) {
                        newStep.frequency = Math.max(newStep.frequency - fxRange * 100, 0)
                    }
                    else {
                        newStep.frequency = newStep.frequency + fxRange * 100
                    }
                }
                else if (effect === SoundExpressionEffect.Warble) {
                    if (i % 2 === 0) {
                        newStep.frequency = Math.max(newStep.frequency - fxRange * 1000, 0)
                    }
                    else {
                        newStep.frequency = newStep.frequency + fxRange * 1000
                    }
                }

                steps.push(newStep)
            }
        }

        const out = control.createBuffer(12 * (steps.length - 1));
        const stepDuration = Math.floor(duration / (steps.length - 1))

        for (let i = 0; i < steps.length - 1; i++) {
            const offset = i * 12;
            out.setNumber(NumberFormat.UInt8LE, offset, waveToValue(waveShape));
            out.setNumber(NumberFormat.UInt16LE, offset + 2, steps[i].frequency);
            out.setNumber(NumberFormat.UInt16LE, offset + 4, stepDuration);
            out.setNumber(NumberFormat.UInt16LE, offset + 6, steps[i].volume);
            out.setNumber(NumberFormat.UInt16LE, offset + 8, steps[i + 1].volume);
            out.setNumber(NumberFormat.UInt16LE, offset + 10, steps[i + 1].frequency);
        }

        return out;
    }

    function waveToValue(wave: WaveShape) {
        switch (wave) {
            case WaveShape.Square: return 15;
            case WaveShape.Sine: return 3;
            case WaveShape.Triangle: return 1;
            case WaveShape.Noise: return 18;
            case WaveShape.Sawtooth: return 2;
        }
    }


    /**
     * Generate a random similar sound effect to the given one.
     *
     * @param sound the sound effect
     */
    //% blockId=soundExpression_generateSimilarSound
    //% block="randomize $sound"
    //% sound.shadow=soundExpression_createSoundEffect
    //% weight=0 help=music/randomize-sound
    //% blockGap=8
    //% group="Sounds"
    export function randomizeSound(sound: SoundEffect) {
        const res = new SoundEffect();
        res.waveShape = sound.waveShape;
        res.startFrequency = sound.startFrequency;
        res.endFrequency = sound.endFrequency;
        res.startVolume = sound.startVolume;
        res.endVolume = sound.endVolume;
        res.duration = sound.duration;
        res.effect = sound.effect;
        res.interpolation = randomInterpolation();

        res.duration = Math.clamp(
            Math.min(100, res.duration),
            Math.max(2000, res.duration),
            res.duration + (Math.random() - 0.5) * res.duration,
        );

        if (res.waveShape === WaveShape.Noise) {
            // The primary waveforms don't produce sounds that are similar to noise,
            // but adding an effect sorta does
            if (Math.random() < 0.2) {
                res.waveShape = randomWave();
                res.effect = randomEffect();
            }
        }
        else {
            res.waveShape = randomWave();

            // Adding an effect can drastically alter the sound, so keep it
            // at a low percent chance unless there already is one
            if (res.effect !== SoundExpressionEffect.None || Math.random() < 0.1) {
                res.effect = randomEffect();
            }
        }

        // Instead of randomly changing the frequency, change the slope and choose
        // a new start frequency. This keeps a similar profile to the sound
        const oldFrequencyDifference = res.endFrequency - res.startFrequency;
        let newFrequencyDifference = oldFrequencyDifference + (oldFrequencyDifference * 2) * (Math.random() - 0.5);

        if (Math.sign(oldFrequencyDifference) !== Math.sign(newFrequencyDifference)) {
            newFrequencyDifference *= -1;
        }

        newFrequencyDifference = Math.clamp(-5000, 5000, newFrequencyDifference);

        res.startFrequency = Math.clamp(
            Math.max(-newFrequencyDifference, 1),
            Math.clamp(1, 5000, 5000 - newFrequencyDifference),
            Math.random() * 5000,
        );

        res.endFrequency = Math.clamp(1, 5000, res.startFrequency + newFrequencyDifference);

        // Same strategy for volume
        const oldVolumeDifference = res.endVolume - res.startVolume;
        let newVolumeDifference = oldVolumeDifference + oldVolumeDifference * (Math.random() - 0.5);

        newVolumeDifference = Math.clamp(-255, 255, newVolumeDifference);

        if (Math.sign(oldVolumeDifference) !== Math.sign(newVolumeDifference)) {
            newVolumeDifference *= -1;
        }

        res.startVolume = Math.clamp(
            Math.max(-newVolumeDifference, 0),
            Math.clamp(0, 255, 255 - newVolumeDifference),
            Math.random() * 255,
        );

        res.endVolume = Math.clamp(0, 255, res.startVolume + newVolumeDifference);

        return res;
    }

    function randomWave() {
        switch (Math.randomRange(0, 3)) {
            case 1: return WaveShape.Sawtooth;
            case 2: return WaveShape.Square;
            case 3: return WaveShape.Triangle;
            case 0:
            default:
                return WaveShape.Sine;
        }
    }

    function randomEffect() {
        switch (Math.randomRange(0, 2)) {
            case 1: return SoundExpressionEffect.Warble;
            case 2: return  SoundExpressionEffect.Tremolo;
            case 0:
            default:
                return SoundExpressionEffect.Vibrato;
        }
    }

    function randomInterpolation() {
        switch (Math.randomRange(0, 2)) {
            case 1: return InterpolationCurve.Linear;
            case 2: return  InterpolationCurve.Curve;
            case 0:
            default:
                return InterpolationCurve.Logarithmic;
        }
    }

    //% shim=music::queuePlayInstructions
    function queuePlayInstructions(timeDelta: number, buf: Buffer) { }
}

