namespace net {
    export enum ControllerEvent {
        NewScan = 1,
        GotIP = 2,
        LostIP = 3,
        NoScannedNetworks = 4,
        NoKnownNetworks = 5,
        Connecting = 6,
        ConnectionFailed = 7,
        LoginServerStarted = 8
    }
    export class Controller {
        eventID: number
        private _isConnected = false

        onConnectSSIDFailed: (ssid: string) => void;

        constructor() {
            this.eventID = control.allocateEventSource()
        }

        protected setConnected(isConnected: boolean) {
            if (this._isConnected != isConnected) {
                this._isConnected = isConnected
                this.emitEvent(isConnected ? ControllerEvent.GotIP : ControllerEvent.LostIP)
            }
        }

        protected emitEvent(ev: ControllerEvent) {
            control.raiseEvent(this.eventID, ev)
        }

        onEvent(ev: ControllerEvent, h: () => void) {
            control.onEvent(this.eventID, ev, h)
        }

        public scanNetworks(): net.AccessPoint[] {
            this.lastScanResults = this.scanNetworksCore()
            this.emitEvent(ControllerEvent.NewScan)
            return this.lastScanResults
        }

        protected scanNetworksCore(): net.AccessPoint[] {
            return [];
        }

        public startLoginServer(hostName: string): void {

        }

        public isLoginServerEnabled(): boolean {
            return false;
        }

        public socket(): number {
            return -1;
        }

        public socketConnect(socket_num: number, dest: string | Buffer, port: number, conn_mode = TCP_MODE): boolean {
            return false;
        }

        public socketWrite(socket_num: number, buffer: Buffer): void {
        }

        public socketAvailable(socket_num: number): number {
            return -1;
        }

        public socketRead(socket_num: number, size: number): Buffer {
            return undefined;
        }

        public socketClose(socket_num: number): void {
        }

        public hostbyName(hostname: string): Buffer {
            return undefined;
        }
        get isIdle(): boolean { return false; }
        get isConnected(): boolean { return this._isConnected; }
        connectAP(bssid: string, password: string) { return false }
        disconnectAP() { }

        lastScanResults: net.AccessPoint[]
        protected reconnectRunning: {}

        autoconnect() {
            if (this.reconnectRunning)
                return
            const myReconn = {}
            this.reconnectRunning = myReconn
            this.emitEvent(ControllerEvent.Connecting)
            control.runInParallel(() => {
                while (this.reconnectRunning == myReconn) {
                    if (this.isConnected) {
                        pause(1000)
                    } else {
                        this.connectCore()
                        pause(500)
                    }
                }
            })
        }

        disconnect() {
            this.reconnectRunning = null
            this.disconnectAP()
        }

        protected connectCore(): boolean {
            if (control.deviceDalVersion() == "sim") {
                this.connectAP("", "")
                return true
            }

            this.scanNetworks()
            if (!this.lastScanResults || this.lastScanResults.length == 0) {
                net.log(`no networks detected`)
                this.emitEvent(ControllerEvent.NoScannedNetworks)
                return false
            }

            if (!this.reconnectRunning)
                return false

            const wifis = net.knownAccessPoints();
            const ssids = Object.keys(wifis);
            const networks = this.lastScanResults
                .filter(network => ssids.indexOf(network.ssid) > -1);

            if (!networks.length) {
                net.log(`no known networks`)
                this.emitEvent(ControllerEvent.NoKnownNetworks)
                return false
            }

            const priorities = net.accessPointPriorities()
            networks.sort((a, b) => {
                const pa = priorities[a.ssid] || 0
                const pb = priorities[b.ssid] || 0
                return pb - pa || b.rssi - a.rssi
            })

            // try connecting to known networks
            for (const network of networks) {
                net.log(`connecting to ${network.ssid}...`)
                const pwd = wifis[network.ssid]
                if (this.connectAP(network.ssid, pwd)) {
                    net.log(`connected to ${network.ssid}`)
                    return true
                }
                if (!this.reconnectRunning)
                    return false

                if (this.onConnectSSIDFailed)
                    this.onConnectSSIDFailed(network.ssid)
            }

            net.log(`connection failed`)
            this.emitEvent(ControllerEvent.ConnectionFailed)
            return false
        }

        connect(timeout_ms?: number): boolean {
            this.autoconnect()
            pauseUntil(() => this.isConnected, timeout_ms)
            return this.isConnected
        }

        get ssid(): string { return undefined; }
        get rssi(): number { return undefined; }
        get MACaddress(): Buffer { return undefined; }
        get IPaddress(): Buffer { return undefined; }
        public ping(dest: string, ttl: number = 250): number { return -1; }

        // optional dataAvailable event
        public dataAvailableSrc(socket_num: number): number { return -1; }
        public dataAvailableValue(socket_num: number): number { return -1; }
    }
}

net.controllersocket.ts:
namespace net {

    export const SOCK_STREAM = 1
    export const AF_INET = 2
    export const MAX_PACKET = 4000
    export const TCP_MODE = 0
    export const UDP_MODE = 1
    export const TLS_MODE = 2

    export class ControllerSocket implements net.Socket {
        _buffer: Buffer;
        _socknum: number;
        _timeout: number;
        _closed: boolean;
        _openHandler: () => void;
        _closeHandler: () => void;
        _errorHandler: (msg: string) => void;
        _messageHandler: (data: Buffer) => void;

        /** A simplified implementation of the Python 'socket' class, for connecting
    through an interface to a remote device
 */
        constructor(private controller: Controller, private host: string | Buffer, private port: number, private conntype: number = null) {
            if (this.conntype === null) {
                this.conntype = net.TCP_MODE
            }
            this._buffer = hex``
            this._socknum = this.controller.socket()
            this.setTimeout(0)
        }

        /** Connect the socket to the 'address' (which can be 32bit packed IP or
    a hostname string). 'conntype' is an extra that may indicate SSL or not,
    depending on the underlying interface
*/
        public connect() {
            if (!this.controller.socketConnect(this._socknum, this.host, this.port, this.conntype)) {
                this.error(`failed to connect to ${this.host}`)
                return;
            }

            this._buffer = hex``

            if (this._openHandler)
                this._openHandler();
        }

        /** Send some data to the socket */
        public send(data: string | Buffer) {
            //console.log("sock wr: " + data)
            this.controller.socketWrite(this._socknum, net.dataAsBuffer(data))
        }

        private error(msg: string) {
            if (this._errorHandler)
                this._errorHandler(msg)
        }

        onOpen(handler: () => void): void {
            this._openHandler = handler;
        }
        onClose(handler: () => void): void {
            this._closeHandler = handler;
        }
        onError(handler: (msg: string) => void): void {
            this._errorHandler = handler;
        }

        private flushReadBuffer() {
            while (!this._closed && this._messageHandler) {
                const buf = this.read()
                if (buf.length) {
                    this._messageHandler(buf)
                } else {
                    break
                }
            }
        }

        onMessage(handler: (data: Buffer) => void): void {
            if (this._messageHandler === undefined) {
                const src = this.controller.dataAvailableSrc(this._socknum)
                const value = this.controller.dataAvailableValue(this._socknum)
                if (src > 0 && value > 0) {
                    this.flushReadBuffer()
                    control.internalOnEvent(src, value, () => this.flushReadBuffer())
                } else {
                    control.runInParallel(() => {
                        while (!this._closed) {
                            this.flushReadBuffer()
                            pause(200)
                        }
                    })
                }
            }
            this._messageHandler = handler || null;
        }

        /** Attempt to return as many bytes as we can up to but not including '\r\n' */
        public readLine(): string {
            // print("Socket readline")
            let stamp = monotonic()
            while (this._buffer.indexOf(hex`0d0a`) < 0) {
                // there's no line already in there, read some more
                let avail = Math.min(this.controller.socketAvailable(this._socknum), MAX_PACKET)
                if (avail > 0) {
                    this._buffer = this._buffer.concat(this.controller.socketRead(this._socknum, avail))
                } else if (avail < 0 || (this._timeout > 0 && monotonic() - stamp > this._timeout)) {
                    // Make sure to close socket so that we don't exhaust sockets.
                    this.close()
                    throw "Didn't receive full response, failing out"
                } else {
                    pause(20)
                }
            }
            const pos = this._buffer.indexOf(hex`0d0a`)
            const pref = this._buffer.slice(0, pos)
            this._buffer = this._buffer.slice(pos + 2)
            // print("rd: " + this._buffer.length + " / " + pref.length + " :" + pref.toString())
            return pref.toString()
        }

        /** Read up to 'size' bytes from the socket, this may be buffered internally! If 'size' isn't specified, return everything in the buffer. */
        public read(size: number = 0): Buffer {
            // print("Socket read", size)
            if (size == 0) {
                if (this._buffer.length == 0) {
                    let avail = Math.min(this.controller.socketAvailable(this._socknum), MAX_PACKET)
                    if (avail > 0)
                        this._buffer = this.controller.socketRead(this._socknum, avail)
                    if (avail < 0)
                        this.close()
                }
                let ret = this._buffer
                this._buffer = hex``
                return ret
            }

            let stamp = monotonic()
            let to_read = size - this._buffer.length
            let received = []
            while (to_read > 0) {
                // print("Bytes to read:", to_read)
                let avail = Math.min(this.controller.socketAvailable(this._socknum), MAX_PACKET)
                if (avail > 0) {
                    stamp = monotonic()
                    let recv = this.controller.socketRead(this._socknum, Math.min(to_read, avail))
                    received.push(recv)
                    to_read -= recv.length
                } else {
                    pause(20)
                }

                if (avail < 0 || (this._timeout > 0 && monotonic() - stamp > this._timeout)) {
                    break
                }

            }
            // print(received)
            received.unshift(this._buffer)
            this._buffer = pins.concatBuffers(received)
            let ret = null
            if (this._buffer.length == size) {
                ret = this._buffer
                this._buffer = hex``
            } else {
                ret = this._buffer.slice(0, size)
                this._buffer = this._buffer.slice(size)
            }

            return ret
        }

        /** Set the read timeout for sockets, if value is 0 it will block */
        public setTimeout(value: number) {
            this._timeout = value
        }

        /** Close the socket, after reading whatever remains */
        public close() {
            this._closed = true;
            this._buffer = hex``
            this.controller.socketClose(this._socknum)
            if (this._closeHandler)
                this._closeHandler();
        }
    }
}

net.net.ts:
/**
 * Networking, WiFi, web requests
 */
//% weight=1
//% advanced=true
//% icon="\uf1eb" color="#8446cf"
namespace net {
    /**
     * Default priority of net log messages
     **/
    export let logPriority: ConsolePriority = -1;
    export function log(msg: string) {
        console.add(logPriority, "net:" + msg);
    }
    export function debug(msg: string) {
        if (logPriority > ConsolePriority.Debug)
            console.add(ConsolePriority.Debug, "net:" + msg);
    }
    export function fail(reason: string) {
        net.log(`error: ${reason}`);
        throw reason;
    }

    export function monotonic(): number {
        return control.millis() / 1000.0;
    }

    export const enum WifiAPFlags {
        HasPassword = 0x1,
        WPS = 0x2,
        HasSecondaryChannelAbove = 0x4,
        HasSecondaryChannelBelow = 0x8,
        IEEE_802_11B = 0x100,
        IEEE_802_11A = 0x200,
        IEEE_802_11G = 0x400,
        IEEE_802_11N = 0x800,
        IEEE_802_11AC = 0x1000,
        IEEE_802_11AX = 0x2000,
        IEEE_802_LongRange = 0x8000,
    }

    export class AccessPoint {
        flags: WifiAPFlags
        rssi: number
        bssid: Buffer
        channel: number
        constructor(public ssid: string) { }
        static fromBuffer(buf: Buffer) {
            const name = buf.slice(16)
            let endp = name.length - 1
            while (endp > 0 && name[endp] == 0)
                endp--
            endp++
            const res = new AccessPoint(name.slice(0, endp).toString())
            const [flags, _reserved, rssi, channel] = buf.unpack("<IIbB")
            res.flags = flags
            res.rssi = rssi
            res.channel = channel
            res.bssid = buf.slice(10, 6)
            if (res.bssid.toArray(NumberFormat.UInt16LE).every(x => x == 0))
                res.bssid = null
            return res
        }
        toBuffer() {
            /*
            flags: APFlags
            reserved: u32
            rssi: i8 dB {typical_min = -100, typical_max = -20}
            channel: u8 {typical_min = 1, typical_max = 13}
            bssid: u8[6]
            ssid: string {max_bytes = 33}
            */
            const pref = Buffer.pack("<IIbB", [this.flags, 0, this.rssi, this.channel])
            const bssid = Buffer.create(6)
            if (this.bssid) bssid.write(0, this.bssid)
            return pref.concat(bssid).concat(Buffer.fromUTF8(this.ssid))
        }
    }

    export interface Socket {
        connect(): void;
        send(data: string | Buffer): void;
        read(contentLength: number): Buffer;
        close(): void;
        onOpen(handler: () => void): void;
        onClose(handler: () => void): void;
        onError(handler: (msg: string) => void): void;
        onMessage(handler: (data: Buffer) => void): void;
        setTimeout(millis: number): void;
        readLine(): string;
    }

    export class Net {
        private _controller: Controller;
        constructor(private factory: () => Controller) {
            Net.instance = this;
            this._controller = undefined; // null failed to initialize
        }

        static instance: Net;

        get controller(): net.Controller {
            if (this._controller === undefined) {
                net.log(`init controller`)
                this._controller = this.factory();
                if (!this._controller) {
                    net.log(`controller not found`)
                    this._controller = null;
                }
            }
            return this._controller;
        }

        /**
         * Scan for APs
         */
        scanNetworks(): net.AccessPoint[] {
            const c = this.controller;
            try {
                return c ? c.scanNetworks() : [];
            } catch (e) {
                console.error("" + e)
                return [];
            }
        }

        createSocket(host: string, port: number, secure: boolean): net.Socket {
            const c = this.controller;
            if (!c) return undefined;
            const socket = new net.ControllerSocket(c, host, port, secure ? net.TLS_MODE : net.TCP_MODE);
            return socket;
        }

        hostByName(host: string): string {
            const c = this.controller;
            if (!c) return undefined;
            const b = this.controller.hostbyName(host);
            if (b) return b.toString();
            return undefined;
        }
    }

    /**
     * Gets the current Net instance
     */
    export function instance(): Net {
        return net.Net.instance;
    }

    const AP_SECRETS_KEY = "wifi";
    const AP_PRI_KEY = "#wifipriority";
    /**
     * Gets the map of SSID -> password pairs
     */
    export function knownAccessPoints(): StringMap {
        return settings.deviceSecrets.readSecret(AP_SECRETS_KEY) || {};
    }

    export function clearAccessPoint(ssid: string) {
        const ap = knownAccessPoints()
        if (ap[ssid] !== undefined) {
            delete ap[ssid]
            settings.deviceSecrets.setSecret(AP_SECRETS_KEY, ap)
        }
    }

    export function updateAccessPoint(ssid: string, password: string) {
        const k: StringMap = {};
        k[ssid] = password;
        settings.deviceSecrets.updateSecret(AP_SECRETS_KEY, k);
    }

    export function setAccessPointPriority(ssid: string, pri: number) {
        const s = accessPointPriorities()
        if (s[ssid] != pri) {
            s[ssid] = pri
            settings.writeJSON(AP_PRI_KEY, s)
        }
    }

    export function accessPointPriorities() {
        return settings.readJSON(AP_PRI_KEY) || {}
    }

    export function clearAccessPoints() {
        settings.deviceSecrets.setSecret(AP_SECRETS_KEY, undefined);
    }
}

