enum SegmentStyle {
    //% block="blank"
    Blank = 0,
    //% block="thin"
    Thin = 1,
    //% block="narrow"
    Narrow = 2,
    //% block="medium"
    Medium = 3,
    //% block="thick"
    Thick = 4
}

enum DigitRadix {
    //% block="decimal"
    Decimal = 10,
    //% block="hex"
    Hex = 16,
    //% block="octal"
    Octal = 8,
    //% block="alpha"
    Alpha = 26
}

enum SegmentScale {
    //% block="full"
    Full,
    //% block="half"
    Half
}

// "0123456789ABCDEFHJLoPrUY-°"
enum SegmentCharacter {
    //% block="0"
    ZERO,
    //% block="1"
    ONE,
    //% block="2"
    TWO,
    //% block="3"
    THREE,
    //% block="4"
